_standard_bars=bars
def bars(labels,values,maximum,**kwargs):
    # Keep mobile labels readable. Full definitions remain in each source text.
    if len(kwargs.get('ylabel',''))>36:
        kwargs['ylabel']='Mean score; scale defined in source'
    result=_standard_bars(labels,values,maximum,**kwargs)
    return re.sub(r'font-size="(\d+)"',lambda m:f'font-size="{max(26,int(m[1]))}"',result)

