def paras(value):
    return [p.strip() for p in value.split('||') if p.strip()]

def add_soc(title,code,section,stem,answer,*,context='general',concepts=None,diagram=None,caption=None,source='equivalence'):
    n=len(SOC)+1
    q=question('soc',n,title,f'SOC.{code:02}',section,stem,paras(answer),difficulty='medium' if n<=20 else 'hard',context=context,concepts=concepts,diagram=diagram,caption=caption)
    SOC.append(q)
    LEDGER.append(evidence(q,'Author reasoning: '+ ' '.join(paras(answer))+' The demanded explanation concerns the supplied mechanism and context, rather than a numerical or thematic inference at SL.',sources=[URL[source]],alternatives=['Accept another accurate, context-linked explanation where it answers the stated demand; illustrative content is not an additive checklist.'],figure={'type':'original qualitative schematic','validation':'Box text reproduces only the stated scenario givens. Connecting lines show sequence or contrast, not proven causal effects or the evaluated psychological conclusion.'} if diagram else None))

def boxes(labels,heading='Illustrative scenario sequence',sequential=True):
    assert 2<=len(labels)<=4
    body=text(360,35,heading,26,'middle'); slot=660/len(labels)
    for i,label in enumerate(labels):
        x=30+i*slot
        body+=rect(x,100,slot-20,150)
        for j,row in enumerate(label.split('|')): body+=text(x+(slot-20)/2,140+35*j,row,26,'middle')
        if sequential and i<len(labels)-1: body+=line(x+slot-20,175,x+slot,175)+line(x+slot-8,168,x+slot,175)+line(x+slot-8,182,x+slot,175)
    body+=text(360,300,'Fictional sequence; arrows indicate order only.' if sequential else 'Fictional scenario; settings shown in parallel.',26,'middle')
    return svg(body,720,330)

# Paper 1A: explanatory understanding, no compulsory named-study recall.
add_soc('Inconsistency and attitude revision',1,'p1-a','Explain cognitive dissonance using one example in which a person could reduce dissonance without changing their behaviour.',
'''Cognitive dissonance is an uncomfortable state arising when relevant cognitions are inconsistent, especially when an action conflicts with a valued attitude. It can motivate attempts to restore consistency; it is not simply uncertainty or having two different preferences.||For example, someone who values sticking to a careful budget but buys an unnecessary item outside their plan might justify the purchase as a rare opportunity that will save money later. This added cognition can reduce the experienced inconsistency without returning the item or changing the spending behaviour. Changing an attitude, adding a consonant cognition or minimizing the issue can be distinguished from changing the action. The example should identify the conflict and explain how the proposed response addresses it.''',concepts=['change'],source='dissonance')
add_soc('Why an initial request can matter',2,'p1-a','Explain the foot-in-the-door compliance technique, using an example that distinguishes compliance from obedience.',
'''The technique begins with a small request that a person accepts and is followed by a larger related request. An initial voluntary commitment may encourage a consistent self-perception, making later agreement more likely; the effect is probabilistic rather than guaranteed.||For example, a community group first asks an adult to display a recycling reminder and later asks them to volunteer for a collection. Both are explicit requests, with refusal possible. This is compliance rather than obedience to an authority’s command: the requester need not possess formal power. Simply presenting a large request without an accepted initial request would not illustrate the sequence.''',concepts=['change','responsibility'],source='compliance')
add_soc('Two routes to matching a group',3,'p1-a','Explain how normative and informational social influence can produce similar public behaviour for different reasons. Use an example.',
'''Normative influence involves matching others to obtain acceptance or avoid social rejection. Informational influence involves treating others’ judgments as evidence about reality, especially under uncertainty. The same public response therefore need not show the same private belief.||A newcomer might agree with a group’s choice of a route either to avoid standing out, despite privately preferring another route, or because experienced members seem to know the area. The first account concerns social approval, while the second concerns perceived accuracy. A developed example should make the different motives explicit rather than defining all conformity as unthinking imitation.''',concepts=['measurement','perspective'])
add_soc('Dimensions rather than cultural boxes',4,'p1-a','Explain how a cultural dimension can be used in psychology without assuming that every person in a cultural group has the same characteristics.',
'''A cultural dimension describes a patterned contrast in values or practices, such as the relative emphasis placed on personal goals and interdependence. It can organize hypotheses about social expectations without defining a fixed type for every individual.||For example, researchers might consider whether family consultation is expected during educational decisions. Individuals within the same community can differ in their preferences and circumstances, and the same individual can act differently across settings. A group tendency cannot simply be assigned to a particular person. The explanation should use the dimension as a contextual framework and acknowledge within-group variation, rather than treating nationality as a psychological diagnosis.''',concepts=['perspective','bias'])
add_soc('Understanding meaning from within',5,'p1-a','Explain an emic approach to psychological research, including why consulting local participants can change an operational definition.',
'''An emic approach investigates behaviour through the meanings and categories of a particular cultural setting. Rather than beginning with a supposedly universal definition, the researcher tries to understand how local participants interpret the phenomenon.||For example, an initial definition of respectful classroom participation might count only spontaneous speaking. Local consultation could reveal that attentive listening and waiting for another speaker to finish also communicate respect in that setting, prompting revised observation categories. The researcher should investigate these meanings rather than assume that all silence is respectful. Consultation does not automatically remove bias or make every account equivalent; the explanation should show what is learned about the construct and how this changes its measurement.''',concepts=['measurement','perspective'])
add_soc('When a common measure is an etic tool',7,'p1-a','Explain an etic approach using a cross-cultural example, and distinguish it from assuming that a translated measure is automatically equivalent.',
'''An etic approach seeks concepts or relationships that can be compared across cultural settings using a common framework. For instance, a researcher may investigate whether perceived belonging relates to participation in different communities using the same proposed construct.||A translated questionnaire is only a starting point: the relevant behaviour and response scale must have comparable meanings. A word such as independence may signal competent self-direction in one setting but social abandonment in another. Testing local interpretations and revising items can support a defensible common measure. An etic aim is comparison, not proof that the original researcher’s categories are universal.''',concepts=['measurement','bias'])
add_soc('Two dimensions of adapting across cultures',8,'p1-a','Explain why heritage-culture maintenance and participation in a wider society should be treated as separate dimensions in an acculturation model.',
'''Acculturation involves psychological and behavioural changes during continuing contact between cultural settings. Maintaining heritage practices and engaging with a wider society need not be opposite ends of one scale: a person may value both, one, or neither.||For example, someone can continue a heritage language at home while actively participating in a new school. In Berry’s framework this is compatible with integration, whereas participation combined with little heritage maintenance resembles assimilation. The model describes orientations rather than fixed identities. Opportunities, exclusion and institutional policies constrain what is possible, so neither successful adjustment nor difficulty should be attributed solely to a person’s chosen strategy.''',concepts=['change','perspective'],source='acculturation')
add_soc('Learning that is not immediately performed',10,'p1-a','Explain social learning theory using an example in which a person learns an action from a model but does not immediately perform it.',
'''Social learning theory explains acquisition of behaviour through observing models and the consequences associated with their actions. Attention and retention support learning, while ability and motivation affect whether the action is performed. Direct reinforcement of the observer is therefore not necessary for every learned action.||A student may watch a peer demonstrate a helpful way to welcome a new classmate and remember the sequence, but wait until another newcomer arrives before using it. Absence of immediate imitation does not prove absence of learning. The explanation should distinguish observation, retention and later opportunity from a simple reward-driven account of the observer’s behaviour.''',concepts=['change','measurement'],source='learning')

# Paper 1B: sixteen distinct unseen situations; schematic givens are qualitative.
add_soc('Advocacy after a personal commitment',1,'p1-b','Original fictional scenario: Leena publicly promotes walking short journeys because she values cleaner air. She then chooses to drive a short journey for convenience, despite a safe route being available. Later she says that one short drive makes no environmental difference. Explain how cognitive dissonance could account for Leena’s response.',
'''The relevant inconsistency is between Leena’s valued environmental position, made salient through public advocacy, and her freely chosen convenient drive. If she experiences that discrepancy as a threat to consistency, dissonance could motivate an explanation that reduces its importance.||Saying that one journey makes no difference minimizes the significance of the conflicting action and adds a justification while leaving the driving behaviour unchanged. Public commitment can make the inconsistency harder to dismiss, but the account does not require that an observer directly see discomfort.||The scenario is compatible with this explanation rather than proving it: Leena might sincerely hold the new judgment or face unreported constraints. A strong application links the actual cognitions and the specific minimizing statement, not merely labels her hypocritical.''',context='health-wellbeing',concepts=['change','perspective'],diagram=boxes(['Values|cleaner air','Chooses|short drive','Minimizes|one journey']),source='dissonance')
add_soc('A smaller health-campaign request',2,'p1-b','Original fictional scenario: A community organizer asks an adult to lead six optional weekly neighbourhood walks. The adult refuses. The organizer then asks the same adult to help advertise a single walk, which the adult accepts. Explain how the door-in-the-face technique could account for this sequence.',
'''Door-in-the-face begins with a comparatively large request that is refused, followed by a smaller request. The organizer’s move from leading six walks to advertising one can appear to be a concession, encouraging the adult to reciprocate with a concession of their own.||The second request is also made to seem less demanding by contrast with the first. The organizer makes both requests, allowing the perceived compromise to remain linked to the same social interaction. The adult’s acceptance is compliance with an explicit request rather than evidence that their private health beliefs changed.||This account is plausible rather than certain: advertising one walk may simply be convenient and attractive. A developed answer applies reciprocal concession or contrast to the specified requests and does not confuse this large-to-small sequence with foot-in-the-door.''',context='health-wellbeing',concepts=['change','responsibility'],diagram=boxes(['Six walks|declined','One advert|requested','Smaller role|accepted']),source='compliance')
add_soc('Agreement in a visible group chat',3,'p1-b','Original fictional scenario: Amir privately prefers a quiet venue for a reunion. In a group chat, friends praise a crowded venue and joke that quiet venues are boring. Amir endorses the crowded venue in the chat but continues to tell his sibling he prefers the quiet one. Explain normative social influence in this situation.',
'''Normative influence concerns gaining acceptance or avoiding negative social evaluation. The friends’ joking makes the social cost of disagreeing salient, and Amir’s public endorsement can help him present himself as an accepted group member.||His continuing private preference for the quiet venue is consistent with public compliance without internal acceptance. No change in knowledge about venue quality is required by this account; the salient issue is how his response will be received by friends.||An explanation should link the visible chat, the joking and the public–private difference rather than assert that he has adopted the majority’s belief. Other motives remain possible, such as valuing group harmony, but they do not require obedience to a formal authority. Normative conformity is an interpretation of these details, not a label for every group decision.''',context='human-relationships',concepts=['measurement','perspective'],diagram=boxes(['Private|quiet venue','Public chat|crowded|endorsed','Later private|quiet preferred']))
add_soc('Family consultation and a career choice',4,'p1-b','Original fictional scenario: Rina values a design course but also considers how its timetable will affect caring for a relative. Her cousin values the same family relationships but makes a different decision because their care arrangements differ. Explain how individualism–collectivism can inform this situation without reducing either cousin to a cultural stereotype.',
'''The dimension can draw attention to the relative emphasis on personal preference and obligations within interdependent relationships. Rina’s consideration of care arrangements suggests that her educational choice is embedded in family responsibilities rather than evaluated only as an individual achievement.||However, the cousins’ different decisions do not show that one possesses a fixed individualist personality and the other a fixed collectivist personality. Both value family, while their practical opportunities differ. A cultural framework concerns patterns of meaning and expectation, not a deterministic classification of every act.||A strong answer connects the dimension to the decision’s social meaning while retaining individual agency and situational constraints. It should not infer national values from names, treat family care as pathological, or assume that pursuing the course necessarily rejects family relationships.''',context='human-development',concepts=['perspective','bias'])
add_soc('A local account of feeling well',5,'p1-b','Original fictional scenario: A researcher plans a well-being interview using only questions about positive feelings. Community advisers explain that some participants describe feeling well in terms of dependable relationships and being able to meet everyday obligations. Explain how an emic approach could improve this interview.',
'''An emic approach would investigate what well-being means within this setting before treating the researcher’s positive-feeling questions as a complete account. Advisers have identified relational and practical meanings that the initial definition may miss.||The researcher could ask open, neutral questions about participants’ own indicators of feeling well, probe examples of dependable relationships and obligations, and work with local collaborators to refine the interview guide. This can increase the relevance of the operational definition and reduce an imposed cultural framework.||The improvement is not simply adding more questions or declaring local accounts beyond criticism. Participants may disagree, and researcher interpretation remains involved. A developed response explains why these particular new prompts capture previously omitted meanings, while avoiding leading participants to say that obligations always improve well-being.''',context='health-wellbeing',concepts=['measurement','perspective','responsibility'],source='equivalence')
add_soc('Learning an unspoken welcoming practice',6,'p1-b','Original fictional scenario: At a neighbourhood gathering, a child watches older relatives pause to greet each new arrival before beginning a shared activity. Over time the child starts doing the same, and adults gently remind the child when they forget. Explain enculturation in this situation.',
'''Enculturation is the process through which people acquire the meanings, norms and practices of the cultural setting in which they develop. The child’s repeated participation in gatherings provides opportunities to learn that greeting arrivals is expected and meaningful.||Observation of relatives supplies models, while reminders and everyday feedback communicate the norm. The child gradually incorporates the practice rather than simply possessing it because of biological inheritance or group membership. Shared participation can also explain when the greeting is appropriate, not only its outward form.||A strong application relates learning to the repeated social setting and feedback. It need not assume that every child will respond identically or that the custom is permanently fixed. This is learning within a cultural setting, distinct from adapting across cultural settings through acculturation.''',context='human-development',concepts=['change','perspective'],diagram=boxes(['Watches|greetings','Starts|greeting','Receives|reminders']),source='learning')
add_soc('Comparing feedback across schools',7,'p1-b','Original fictional scenario: A team wants to compare whether feedback helps students feel competent in two school communities. It proposes one competence questionnaire for both settings, but local interviews suggest that being competent may include helping peers in one setting and completing tasks independently in the other. Explain how a defensible etic approach could address this problem.',
'''An etic approach seeks a common framework that makes comparison meaningful. Here the proposed construct is perceived competence, but using an identical questionnaire does not establish that the construct has the same meaning in both communities.||The team could examine local definitions, check whether items cover relevant aspects of competence in both settings, and develop shared items where functional meanings overlap. Translation and response options would also need checking. Locally meaningful items may be retained separately rather than forced into a single score.||The purpose is to compare an equivalent construct, not to assume that one school’s definition is the universal standard. A strong response applies equivalence to helping peers versus independent completion and avoids concluding that either community is inherently more capable from differing interpretations of competence.''',context='learning-cognition',concepts=['measurement','bias'],source='equivalence')
add_soc('Language use across different settings',8,'p1-b','Original fictional scenario: A recently arrived student speaks a heritage language with family and joins a local-language drama club. A teacher says that using the heritage language shows failure to adapt. Explain the student’s behaviour using a two-dimensional model of acculturation.',
'''A two-dimensional model treats maintaining heritage culture and participating in a wider society as separate orientations. The student’s family language use supports heritage maintenance, while joining the drama club indicates participation in the new setting. These activities can coexist rather than cancel each other out.||In Berry’s framework this pattern is compatible with integration. The teacher’s judgment assumes a one-dimensional assimilation model in which heritage maintenance must disappear for adaptation to occur. That assumption is not warranted by the described behaviour.||The categories are interpretive tools rather than permanent diagnoses, and language choice alone cannot establish the student’s overall adjustment or private identity. A strong application explains the two actual behaviours and recognizes that institutional acceptance and accessible activities influence the options available to the student.''',context='human-relationships',concepts=['perspective','responsibility'],diagram=boxes(['Home|heritage language','Drama club|local language'],'Two settings in one student’s life',False),source='acculturation')
add_soc('A badge changes who counts as us',9,'p1-b','Original fictional scenario: Volunteers at a festival receive arbitrary blue or green badges. After working together in badge groups, some describe their own group as more reliable and prefer its members for desirable tasks, despite having no performance information about the other group. Explain how social identity theory could account for this preference.',
'''Social identity theory concerns how membership in social categories contributes to self-concept. The badges and group work make an in-group distinction salient, allowing volunteers to compare their group with an out-group.||Describing their own group as more reliable can provide positive distinctiveness and support a valued group identity. Preferring its members without relevant performance information is consistent with in-group favouritism rather than an evidence-based judgment about ability. The arbitrary badges need not reflect pre-existing hostility for categorization to matter.||The account does not make favouritism inevitable or establish that the groups truly differ. Cooperation across badges, alternative identities or stronger performance evidence could alter the response. A developed answer connects categorization, identification and comparison to the specific reliability judgment and task allocation rather than using social identity as a synonym for friendship.''',context='human-relationships',concepts=['bias','perspective'],diagram=boxes(['Blue badge|working group','Green badge|working group'],'Arbitrary festival groups',False),source='identity')
add_soc('A model who corrects an error',10,'p1-b','Original fictional scenario: A student watches a peer make a mistake in a practice problem, calmly check the method and correct it. The peer receives appreciative feedback for explaining the correction. Later, the observer uses the same checking routine when working alone. Explain this behaviour using social learning theory.',
'''The observer can attend to the peer’s visible checking routine, retain its steps and reproduce them when a similar problem occurs. This makes learning through a model plausible even though the observer was not directly rewarded during the demonstration.||Appreciative feedback to the model can function as vicarious reinforcement: the observer sees a valued consequence associated with explaining and correcting an error, which may increase motivation to use the routine. Motor or cognitive ability and a later opportunity also matter for performance.||A strong explanation maps the observed steps and later independent use onto the theory rather than treating the observer as merely copying an answer. The incident supports a possible social-learning account, but prior instruction or independent reasoning could also contribute. Learning an error-checking process is not the same as automatically imitating every action of a successful peer.''',context='learning-cognition',concepts=['change','causality'],diagram=boxes(['Peer|checks an error','Feedback|appreciative','Observer later|checks alone']),source='learning')
add_soc('Defending an expensive course',1,'p1-b','Original fictional scenario: Joel freely chooses an expensive revision course and tells friends that he made an excellent decision. When he encounters an equally useful free resource, he insists that the paid resource must be superior without comparing their content. Explain how cognitive dissonance could account for his insistence.',
'''Joel’s investment and public endorsement can make the course part of a valued judgment about his own decision-making. Discovering an equally useful free alternative conflicts with the belief that paying was necessary or especially wise, potentially producing dissonance.||Insisting that the paid course must be better can restore consistency by increasing its perceived value and dismissing the alternative, without recovering the money or changing the original choice. Free choice and the salience of the commitment make this account more specific than merely noting that he prefers expensive products.||The scenario does not prove dissonance: price may be used as a quality cue, and confirmation bias could influence what he notices. A developed response explains the commitment–inconsistency–justification relationship while treating those alternatives as compatible possibilities rather than redefining every biased judgment as dissonance.''',context='learning-cognition',concepts=['bias','change'],source='dissonance')
add_soc('From a small contribution to volunteering',2,'p1-b','Original fictional scenario: A residents’ association first asks adults to suggest one idea for a welcome event. A week later it asks those who agreed to help run the event for an afternoon. Explain how the foot-in-the-door technique could influence acceptance of the later request, without assuming it will always succeed.',
'''The first request is small and voluntary, while the later request requires a substantially greater commitment. Agreement to contribute an idea may make an identity such as helpful neighbour salient and encourage consistency with that initial involvement.||The association can therefore increase the likelihood of compliance with the afternoon request without using a command or direct threat. The connection between the two requests matters: both concern the same welcome event, making the later request intelligible as an extension of the earlier contribution.||Success is not guaranteed, because time, competing responsibilities and perceived manipulation may prevent agreement. A strong application explains the psychological significance of initial commitment, rather than assuming that the association has authority over residents or that accepting a small request removes their continuing right to refuse.''',context='human-relationships',concepts=['change','responsibility'],source='compliance')
add_soc('Following others when information is uncertain',3,'p1-b','Original fictional scenario: On an unfamiliar walking trail, Noura sees experienced walkers choose the left branch. The signs are unclear, and she follows them because she thinks they probably know the route. She says she would take the right branch if a reliable map showed it was correct. Explain informational social influence in this situation.',
'''Informational influence occurs when a person treats others’ actions as evidence about an uncertain situation. The unclear signs create uncertainty, and the walkers’ apparent experience gives their route choice informational value for Noura.||Her stated willingness to change direction after seeing a reliable map is consistent with an accuracy motive rather than a need to win approval. Following the group need not imply low confidence in all her judgments or blind obedience to authority. It can be a reasonable response when relevant knowledge is unevenly distributed.||A developed answer explains why these particular people are treated as useful sources and how uncertainty affects the decision. The walkers could still be wrong, so informational influence describes the process, not proof that the chosen route is safe or correct. Normative motives may coexist but are not necessary to explain the supplied details.''',context='health-wellbeing',concepts=['perspective','causality'])
add_soc('A norm changes across generations',6,'p1-b','Original fictional scenario: Grandparents learned that children should wait to be invited before joining adult conversation. In the same family today, parents explicitly encourage children to ask questions and praise thoughtful contributions. Explain how enculturation can account for both continuity and change in children’s participation.',
'''Enculturation transmits expectations through participation, models and social feedback. The grandparents’ earlier practice could have been learned through observing deference and receiving reminders to wait, rather than arising automatically with age.||Current children encounter a different pattern of encouragement and praise, which communicates that asking questions can be appropriate. They can acquire a revised norm within an ongoing family relationship, while retaining continuity in values such as respect and engagement. Enculturation therefore need not mean exact copying of an unchanging tradition.||An answer should connect the contrasting social feedback to learned expectations, without inferring that all grandparents or all children share one fixed value system. Age, historical conditions and individual temperament may also matter. The scenario illustrates a process through which cultural practices can be reproduced and renegotiated rather than a genetic explanation for generational differences.''',context='human-development',concepts=['change','perspective'],source='learning')
add_soc('Group loyalty and seeking support',9,'p1-b','Original fictional scenario: A workplace team describes itself as the group that always copes without help. A new member wants support with a demanding shift but worries that asking will make them seem unlike the team. Explain how social identity theory could help account for this concern.',
'''The team’s coping ideal offers a positively valued image of what members of the in-group are like. If the new member identifies with that group, being recognized as a genuine member can become part of their self-concept.||Requesting support may then seem to threaten fit with the group norm or the positive distinctiveness of a team that prides itself on independence. The concern is not evidence that asking for help actually makes someone less capable; it reflects the meaning attached to membership and comparison.||A strong explanation links identity, the stated norm and the anticipated social evaluation. It should acknowledge that supportive subgroups or a broader professional identity could encourage help-seeking instead. The theory provides a plausible mechanism for the concern, while workload, prior experiences and real workplace sanctions might also affect the member’s choice.''',context='health-wellbeing',concepts=['perspective','responsibility'],source='identity')
add_soc('Remembering an inclusive action',10,'p1-b','Original fictional scenario: A younger sibling watches an older sibling invite an isolated neighbour into a game. The older sibling explains the invitation and receives a friendly response. The younger sibling later describes what to do but has not yet had a suitable chance to do it. Explain what social learning theory would and would not allow you to conclude.',
'''Attention to the invitation and retention of its explanation could allow the younger sibling to learn a way of including others. The friendly response provides an observed positive consequence that may influence later motivation through vicarious reinforcement.||Being able to describe the action is consistent with retained knowledge, even though overt imitation has not occurred. Social learning theory distinguishes acquiring a response from performing it; performance also depends on opportunity, ability and motivation. The absence of a suitable chance is therefore relevant to interpreting the lack of behaviour.||However, description alone does not establish that the child will act inclusively in every future situation, or that the observed episode is the only source of knowledge. A developed answer makes a qualified inference about learning and avoids treating either verbal recall or absent performance as a complete measure of a stable prosocial disposition.''',context='human-relationships',concepts=['measurement','change'],diagram=boxes(['Observes|invitation','Can describe|the action','Opportunity|not yet']),source='learning')

# Essay records are completed below; each has a distinct concept/context demand.
add_soc('Changing a health belief or changing a health practice?',1,'p1-c','Discuss cognitive dissonance as an explanation of change in health-related behaviour. Integrate the concepts of change and causality, and use psychological knowledge and relevant examples. You are not required to recall details of a particular named study.',
'''Dissonance offers a mechanism through which a discrepancy between valued beliefs and actions can motivate change. Someone committed to sustainable, active travel may experience conflict when repeatedly choosing a convenient car journey. Changing the action could restore consistency, especially where the person experiences genuine choice and the commitment is personally meaningful. This gives change a psychological explanation rather than treating information alone as sufficient.||However, a reduction in dissonance is not equivalent to healthier behaviour. The person may minimize the significance of short journeys, question the health message or add a justification about time pressures. These responses alter the meaning of the inconsistency while preserving the action. The distinction matters when a campaign measures a more positive attitude or a persuasive explanation and claims a behavioural success.||Causal evaluation requires separating dissonance from practical opportunity, social approval and pre-existing commitment. A freely chosen public promise may strengthen consistency concerns but also create reputational pressure. Later walking could reflect an improved route or support from friends rather than discomfort alone. Measures of felt conflict, private attitude and subsequent behaviour would offer different evidence; self-reports of discomfort can themselves be influenced by expectations.||A proportionate conclusion is that dissonance can explain one route to change and can also explain resistance through rationalization. Its usefulness depends on conditions that make the inconsistency salient and on whether changing behaviour is feasible. It should therefore be integrated with social and situational explanations. Claiming that all inconsistency produces health improvement would ignore both alternative dissonance-reduction strategies and constraints on action.''',context='health-wellbeing',concepts=['change','causality'],source='dissonance')
add_soc('Compliance and meaningful consent',2,'p1-c','Evaluate the use of compliance techniques in community health promotion with reference to responsibility. Consider both potential benefits and the conditions under which apparent agreement may be misleading.',
'''Compliance techniques can make a beneficial request more likely to be accepted without a direct command. A small initial commitment, such as requesting a walking-group timetable, may make a later invitation to attend seem consistent with a helpful self-image. A large request followed by a smaller one can create reciprocal-concession pressure. These mechanisms may lower barriers to community participation, but the social process needs to be distinguished from informed endorsement.||Responsibility concerns how organizers influence people and interpret their responses. A gradual, transparent invitation with an easy refusal can support participation while preserving choice. Concealing the true sequence, exaggerating benefits or targeting people who depend on the organizer creates a different ethical situation. Accepting an invitation under social pressure does not establish that a person understands the activity or wants continuing involvement.||Potential benefits must be assessed against practical fit and the meaning of outcomes. Attendance at one event may be useful without demonstrating a lasting health change. A person may initially agree to avoid embarrassment but subsequently enjoy the group; another may withdraw because the schedule excludes them. Neither response can be explained entirely by the technique. Measuring private preferences, attendance and continued engagement would help distinguish those possibilities.||The strongest judgment is conditional: influence is not inherently irresponsible, because almost every invitation has a social context. It becomes more defensible when the request is truthful, proportionate and genuinely optional, and when organizers avoid interpreting compliance as blanket consent. A successful campaign should be evaluated through relevant, sustained outcomes and participant experience rather than a high initial agreement rate alone.''',context='health-wellbeing',concepts=['responsibility','measurement'],source='compliance')
add_soc('Public conformity and private relationships',3,'p1-c','To what extent does measurement affect explanations of conformity in human relationships? Discuss the distinction between public agreement and private acceptance, using psychological knowledge and relevant examples.',
'''Conformity refers to alignment with a group, but different measures can capture different aspects of that alignment. In a friendship group, publicly endorsing a popular venue can protect acceptance even when the person privately prefers another. A public choice measure would register conformity, while an anonymous preference measure might show little change. Measurement therefore affects which psychological process the evidence can support.||Normative and informational influence offer competing, sometimes complementary accounts. Visible responses and jokes about dissent can make evaluation concerns salient. In contrast, uncertain group members may use experienced friends as evidence and privately adopt their judgment. Public agreement alone cannot distinguish these motives, and a private questionnaire may still be influenced by imagined judgment or a desire to appear consistent.||The design and timing of measures also matter. Measuring a private preference first can make consistency salient; asking immediately after group discussion may capture temporary coordination rather than an enduring belief. Later behaviour in a new setting offers another test, but differences may reflect changed information or opportunities. An interview can explore the meaning of agreement, yet retrospective explanations are not direct observations of the process that produced it.||Measurement substantially shapes explanations but does not make every interpretation equally defensible. Triangulating public responses, confidential judgments and later conduct can narrow alternatives if each measure is appropriate to the relationship context. A qualified conclusion should specify whether the evidence supports public accommodation, internal acceptance or both. Equating all observable matching with loss of independent belief would exceed what any single public response can establish.''',context='human-relationships',concepts=['measurement','bias'])
add_soc('Using cultural dimensions in classrooms',4,'p1-c','Discuss the value and limitations of cultural dimensions for understanding learning and cognition. Integrate perspective and measurement, and avoid treating national or community averages as fixed traits of individuals.',
'''Cultural dimensions can make otherwise unnoticed assumptions about learning visible. A classroom organized around independent achievement may treat speaking first as confidence, whereas another setting may value coordinated contributions and attentiveness to others. Considering individualism–collectivism can generate hypotheses about goals, feedback and the meaning of participation. The value is a broader perspective on learning rather than a ranking of cultures.||Measurement becomes crucial when dimensions are used to compare groups. National background is an imperfect proxy for a person’s values, and the same questionnaire item may have different meanings across settings. Quiet participation may indicate disengagement, respect, uncertainty about language or active reflection. If researchers use one behaviour as a universal indicator of motivation, apparent cultural differences may partly reflect the measure.||Dimensions also risk hiding variability and context. A learner may pursue personal mastery while strongly valuing peer support, or behave differently in assessed discussion and an informal club. Institutions, resources, previous teaching and migration experience can influence the same outcomes attributed to culture. Group tendencies can guide questions but cannot identify the motive of an individual student without further evidence.||A balanced conclusion retains cultural dimensions as flexible organizing tools while rejecting deterministic labels. Their explanatory strength improves when researchers investigate local meanings, examine within-group variation and use measures shown to support meaningful comparison. Combining an etic comparative framework with emic inquiry can reveal both shared processes and context-specific forms. Simply matching an individual to a country score provides a weak explanation of how that student actually learns.''',context='learning-cognition',concepts=['perspective','measurement'],source='equivalence')
add_soc('Local meanings in well-being research',5,'p1-c','Evaluate an emic approach to understanding health and well-being with reference to perspective and responsibility. Consider how local relevance can be combined with critical scrutiny.',
'''An emic approach begins with how people in a setting understand their experiences. Well-being might include fulfilling responsibilities, reciprocal relationships or a sense of spiritual continuity as well as positive feelings. Investigating these meanings can challenge a narrow imported definition and improve the relevance of interviews or support programmes. Perspective matters because the researcher’s initial categories shape what can be recognized as important.||Responsibility includes whose voices count as local knowledge. Consulting only prominent community leaders may silence young people, newcomers or people who disagree with prevailing expectations. Confidential interviewing, inclusive recruitment and attention to power can reveal variation rather than presenting one authoritative account as the voice of an entire culture. Researchers must also explain how their own position influences access and interpretation.||Local relevance does not exempt findings from evaluation. A meaningful account may be internally contested, and practices valued by some participants may constrain others. Emic work can generate rich explanations, but a small purposive sample cannot automatically establish prevalence or the efficacy of a health intervention. Its conclusions concern meanings and processes unless the design supports broader claims.||The most defensible evaluation is therefore neither that emic work is uniquely authentic nor that only standardized measures are scientific. Carefully conducted emic inquiry can expose omitted constructs and inform ethically relevant practice, while transparent analysis and consideration of contrasting accounts permit scrutiny. Where comparison is needed, locally grounded findings can help develop a common framework rather than simply replacing one imposed universal with another unexamined cultural generalization.''',context='health-wellbeing',concepts=['perspective','responsibility'],source='equivalence')
add_soc('Enculturation across a changing childhood',6,'p1-c','Discuss enculturation as an explanation of change in human development. Integrate change and causality, including the problem of distinguishing social learning from age and historical context.',
'''Enculturation explains how developing people learn the practices and meanings of their cultural setting through models, participation, instruction and feedback. A child can learn when to speak in a gathering by observing relatives and experiencing how contributions are received. Change is therefore more than acquiring isolated behaviours: the child can develop an understanding of when and why an action is appropriate.||The process includes continuity and negotiation. Adults may retain a value such as respect while encouraging new forms of participation, allowing children to learn a revised expression of that value. Peers, schools and media provide additional models that may conflict with family expectations. Enculturation consequently need not predict uniform development or passive copying of a fixed tradition.||Causal claims require care because age differences can have several explanations. Older children may have more social experience, but also greater language ability, different responsibilities or exposure to different historical events. Cross-sectional observations cannot show that every child passes through the same changes. Longitudinal work, detailed observation of feedback and comparison of settings can strengthen explanations without eliminating all alternative influences.||A proportionate conclusion is that enculturation supplies a powerful account of how social context becomes part of development, while interacting with maturation and individual agency. The strongest explanations identify the particular practices and learning opportunities involved, rather than treating membership in a cultural group as a cause by itself. Developmental patterns should be explained through observable processes and their changing contexts, not assumed from age or ancestry alone.''',context='human-development',concepts=['change','causality'],source='learning')
add_soc('Can belonging be compared fairly?',7,'p1-c','Evaluate an etic approach to comparing belonging in human relationships with reference to measurement and bias. Consider why identical procedures may still produce an unfair comparison.',
'''An etic approach seeks a framework that can be applied across settings, potentially revealing shared processes in human relationships. A common belonging measure could help investigate whether inclusion relates to participation in different communities. Standardized administration can reduce some procedural differences and make a comparison easier to interpret, but identical wording is not the same as equivalent meaning.||Measurement bias can arise if belonging is defined only through one setting’s preferred behaviours. Frequent independent social activity may signify connection for some participants, while dependable reciprocal obligations matter more to others. Translation, response styles and expectations about disclosing feelings can influence scores. A difference could therefore concern the instrument rather than the strength of relationships.||A defensible comparison would investigate local interpretations, test whether items represent the intended construct and consider whether common and locally specific indicators should be reported separately. Researchers should also distinguish group averages from individual experiences and account for unequal opportunities to participate. A lower score among recent arrivals might reflect exclusion or a poorly matched questionnaire, not an inherent lack of social commitment.||Etic comparison remains valuable when comparability is treated as a question to establish rather than an assumption. Emic inquiry can help refine the common framework and identify limits to interpretation. The conclusion should be conditional: shared measures can support useful comparisons, but only within the meanings and populations for which they are defensible. Merely administering an unchanged questionnaire in two places provides too little protection against systematic bias.''',context='human-relationships',concepts=['measurement','bias'],source='equivalence')
add_soc('Acculturation, development and available choices',8,'p1-c','Discuss models of acculturation in explaining human development with reference to change and responsibility. Evaluate the claim that adjustment depends mainly on an individual choosing the correct acculturation strategy.',
'''A two-dimensional acculturation framework distinguishes heritage maintenance from participation in a wider society. It can describe how a developing person combines family practices, peer relationships and new institutional settings. Integration, assimilation, separation and marginalization summarize orientations rather than unavoidable stages through which every newcomer progresses. This allows change without assuming that heritage identity must disappear.||The claim of a correct personal strategy is too simple because orientations and opportunities interact. Someone may seek both heritage continuity and wider participation yet encounter exclusion, language barriers or institutions that reject their practices. Conversely, participation in a new school may expand a person’s options. An observed pattern therefore cannot be interpreted as entirely voluntary or as a complete measure of psychological adjustment.||Responsibility concerns how models are used by researchers, teachers and services. Labeling a young person poorly adjusted because of heritage-language use may impose assimilation as the standard of success. At the same time, recognizing structural barriers should not erase individual agency or assume that maintaining every practice is beneficial in every circumstance. Outcomes such as belonging, functioning and distress need appropriate definitions rather than being read directly from a category.||A balanced conclusion is that acculturation models organize important dimensions of developmental change but are not prescriptions or diagnoses. They are strongest when combined with evidence about institutional conditions, relationships and the individual’s own goals. Responsibility for adjustment is distributed across people and environments. A model that recognizes this interaction offers a better explanation than attributing difficulty to choosing the wrong cultural identity.''',context='human-development',concepts=['change','responsibility'],source='acculturation')
add_soc('Changing group identities to reduce conflict',9,'p1-c','To what extent can social identity theory explain both conflict and cooperation in human relationships? Integrate change and perspective and support a qualified conclusion.',
'''Social identity theory explains how group membership contributes to self-concept and how comparison can motivate positive distinctiveness. A salient division between teams may encourage favourable judgments of in-group members and less generous treatment of an out-group. This offers a mechanism for conflict even where categories initially have little substantive importance. It does not require an assumption that people have fixed hostile personalities.||The same perspective can also help explain cooperation. If members come to value a shared identity, or norms within the existing group support fair treatment, cooperation can become identity-consistent. A neighbourhood project may make common membership salient without requiring people to abandon other valued identities. Change therefore depends on how categories and norms are understood, not merely on bringing people into physical proximity.||Limitations remain. Material competition, unequal power, institutional incentives and personal relationships can affect whether a shared identity is credible. An appeal to unity may obscure real inequalities or feel like pressure for a minority group to assimilate. Changes in public cooperative behaviour do not necessarily demonstrate changed private identification, so evidence should match the process being claimed.||The theory can account for both conflict and cooperation to a substantial but conditional extent. Its strength is directing attention to categorization, identification and comparison rather than treating group behaviour as inevitable. It is more persuasive when combined with an analysis of resources, status and context. A reasoned conclusion should explain which identity processes could change and why a particular relationship setting would or would not support that change.''',context='human-relationships',concepts=['change','perspective'],source='identity')
add_soc('What observation can teach a learner',10,'p1-c','Evaluate social learning theory in explaining learning and cognition with reference to causality and measurement. Distinguish learning a response from performing it.',
'''Social learning theory explains how observing models can influence knowledge and behaviour through attention, retention, production and motivation. A learner who watches a peer calmly correct an error can acquire a checking routine without being directly rewarded. Seeing appreciation directed at the model may also influence whether the learner later chooses to use the routine. The theory links cognitive processes with a social environment.||Measurement must distinguish acquisition from performance. Immediate imitation may be absent because the learner lacks an opportunity, expects ridicule or cannot yet execute the response. A later demonstration, explanation or transfer task could provide different evidence. Conversely, copying an action once does not prove a stable skill or understanding: the response may depend on the particular setting or on direct prompting.||Causal claims are stronger when exposure to models is systematically varied and alternative instruction is controlled, but a demonstration can combine several influences. The observer may receive useful information, expectations about success and social approval at the same time. A change cannot automatically be attributed to vicarious reinforcement alone. Observational comparisons also need to consider that interested learners may selectively seek particular models.||The theory offers a valuable account of socially situated learning, especially where direct reinforcement of the observer is absent. Its explanatory limits depend on how the components are operationalized and whether transfer and retention are assessed. A balanced conclusion recognizes that observation can support learning while rejecting the stronger claim that every observed response is acquired, or that lack of overt imitation is evidence that nothing was learned.''',context='learning-cognition',concepts=['causality','measurement'],source='learning')
add_soc('When a reported attitude is a convenient explanation',1,'p1-c','Discuss bias and causality when cognitive dissonance is used to explain students’ evaluations of their learning choices. Use psychological knowledge and relevant examples.',
'''Dissonance can explain why someone who freely chooses a demanding course later values it highly: recognizing costs or alternatives may conflict with a positive view of their decision. Increasing the course’s perceived value could reduce that inconsistency. The account connects commitment, meaning and attitude change, rather than assuming that evaluations are always direct measures of teaching quality.||Bias arises when the explanation is applied selectively. A researcher may interpret every positive review after investment as justification, while ignoring genuine learning benefits or a pre-existing preference. Participants may also present a favourable evaluation to protect reputation. Such self-presentation can resemble dissonance reduction without establishing the same private psychological process. These alternatives should be specified rather than listed as generic flaws.||Causal inference requires evidence that the relevant inconsistency and conditions of commitment matter. Comparing students who voluntarily selected different courses leaves selection, cost and expectations entangled. Even varying an external justification may alter attention or interpretation as well as discomfort. Measuring private evaluation, perceived choice and later behaviour can help, but asking about dissonance may make the hypothesis apparent.||A proportionate judgment is that dissonance is one useful explanation of learning evaluations, not an automatic correction that reveals what students truly think. Researchers should state what observations would count against the account and consider competing mechanisms fairly. The strongest conclusions connect evidence to a particular dissonance process while preserving the possibility of authentic satisfaction, practical constraints and other cognitive biases.''',context='learning-cognition',concepts=['bias','causality'],source='dissonance')
add_soc('A yes is not the whole relationship',2,'p1-c','Evaluate the use of agreement rates to judge the success of compliance techniques in human relationships. Integrate measurement and responsibility.',
'''Agreement rates provide a clear record of responses to requests, and this can help compare how invitation sequences affect participation. A small request followed by a larger one may encourage consistency, while a large refused request followed by a smaller one may elicit reciprocal concession. Observing more agreement can support a claim about compliance under the specified conditions.||However, agreement is not equivalent to private enthusiasm, informed consent or sustained involvement. A neighbour may say yes to preserve a relationship and later feel unable to refuse further requests. Another may initially agree for social reasons but subsequently find the activity valuable. Measuring only the first response conceals these differences and can overstate the quality of the resulting relationship.||Responsibility requires examining how the request is made and who can safely decline. Dependency, status differences and repeated contact can turn an apparently optional request into pressure. Transparent invitations, a continuing right to withdraw and attention to burdens make influence more defensible. High agreement obtained through concealment or embarrassment should not be treated as sufficient evidence of a beneficial intervention.||A balanced evaluation uses agreement alongside relevant conduct, continued participation and participants’ accounts of the interaction. These measures also have limitations, so the objective is a proportionate interpretation rather than one perfect success score. Compliance techniques may help people take a useful first step, but their success in human relationships should be judged in terms of the meaning, freedom and consequences of participation, not the number of people who initially say yes.''',context='human-relationships',concepts=['measurement','responsibility'],source='compliance')
add_soc('Following a group can be rational or risky',3,'p1-c','Discuss conformity in health and well-being with reference to causality and perspective. Evaluate the claim that following a group necessarily reflects poor judgment.',
'''Conformity can arise through different processes, so following a group is not inherently evidence of poor judgment. In an uncertain setting, people may use others’ experience as information. Joining experienced walkers on an unclear route can be an accuracy-oriented decision. In contrast, a person may publicly match a health-related group norm to avoid ridicule while retaining a different private view.||Perspective matters because the same act can have different meanings in different relationships. Shared participation may supply support, reliable information and a sense of belonging, or it may make an unhelpful norm difficult to challenge. A group’s apparent confidence is not proof of expertise. The evaluation should therefore consider the quality of information, the possibility of dissent and the goals of the person following others.||Causal claims need more than a correlation between group membership and behaviour. People can select groups that already match their preferences, and access to resources may shape both membership and health practices. Varying response visibility or information quality could help distinguish normative and informational influences, although public and private motives can coexist. An observed behaviour alone cannot identify the full process.||The claim is therefore too broad. Conformity can support reasonable coordination or propagate error, depending on the evidence and social setting. A justified conclusion should distinguish the psychological route from the accuracy and consequences of its outcome. Understanding those conditions is more useful than classifying all conformity as weakness or assuming that independent disagreement is always the better judgment.''',context='health-wellbeing',concepts=['causality','perspective'])
add_soc('Cultural expectations and developmental diversity',4,'p1-c','Evaluate cultural dimensions as an explanation of human development with reference to perspective and bias. Consider both family expectations and individual variation.',
'''Cultural dimensions can help explain why developmental goals differ across settings. A family may emphasize becoming a dependable contributor to shared responsibilities, while another emphasizes independent decision-making. These emphases can influence learning opportunities, feedback and the meaning of maturity. A cultural perspective therefore challenges the assumption that one pathway is the universal standard of successful development.||Bias appears when a dimension becomes a stereotype or a value judgment. Describing a young person as insufficiently independent may ignore the competence involved in reciprocal family care. Conversely, romanticizing family obligation may conceal pressure or unequal burdens. Researchers should examine participants’ meanings and opportunities rather than automatically interpreting one behaviour as evidence of a fixed collectivist or individualist disposition.||Dimensions also leave causal questions open. Family resources, institutional expectations, migration, historical conditions and temperament may influence the same developmental outcomes. Members of a community can disagree, and a person can value autonomy and relatedness simultaneously. Assigning a national average to a child commits an unwarranted move from group pattern to individual explanation.||A balanced conclusion keeps cultural dimensions as tentative tools for identifying contextual expectations. Their value increases when supported by observations of actual practices, local accounts and evidence of variation within groups. They should inform questions about development rather than predetermine answers. This allows psychology to recognize culturally shaped goals while preserving agency, critical evaluation and the complexity of individual developmental trajectories.''',context='human-development',concepts=['perspective','bias'],source='equivalence')
add_soc('How health practices are transmitted and revised',6,'p1-c','Discuss enculturation in explaining health-related practices with reference to change and responsibility. Consider why transmitting a valued practice and endorsing its health effects are different issues.',
'''Enculturation can explain how health-related practices acquire meaning through everyday participation. Children may observe how adults rest, share food, seek support or respond to illness, receiving feedback about what is expected. Such learning can make practices feel natural without requiring explicit instruction. It offers an account of transmission, not by itself a test of whether a practice improves health.||Change occurs when families and communities adapt to new information, resources or circumstances. A shared food practice might retain its social significance while ingredients or preparation methods change. Peers, institutions and media can provide competing models. Enculturation therefore involves selective interpretation and negotiation rather than exact reproduction of an unchanging tradition.||Responsibility concerns how psychologists evaluate and communicate about these processes. Dismissing a practice as irrational because it is culturally unfamiliar risks overlooking relational benefits and local expertise. Equally, cultural significance does not establish safety or justify withholding relevant evidence. Health outcomes require appropriate independent investigation, while participants’ meanings remain important for understanding uptake and possible unintended effects.||A proportionate conclusion separates explanation from endorsement. Enculturation helps account for why practices persist or change, especially when observation and feedback can be identified. It should be combined with evidence about material constraints, personal preferences and health consequences. Respectful communication can recognize shared meanings while supporting informed revision; treating culture either as an obstacle to eliminate or as beyond critical scrutiny would weaken psychological understanding.''',context='health-wellbeing',concepts=['change','responsibility'],source='learning')
add_soc('Acculturation labels in a learning setting',8,'p1-c','To what extent can models of acculturation help explain change in learning and cognition? Integrate measurement and change, and evaluate the use of language preference as a sole indicator of adaptation.',
'''Acculturation models can help investigate how learners navigate heritage practices and a new educational setting. A student may maintain one language at home while participating actively in a new-language classroom. Treating heritage maintenance and wider participation as separate dimensions allows this pattern to be understood without assuming that successful learning requires complete assimilation.||Measurement matters because a single language preference captures only part of adaptation. Classroom speech may reflect current proficiency, task demands, confidence, access or a wish to maintain valued relationships. It does not directly reveal belonging, cognitive ability or the learner’s overall orientation. Labeling a quiet student separated or poorly adjusted from one observation would exceed the evidence.||Change can also be uneven across settings and time. A learner may gain confidence in discussion before feeling comfortable in informal peer interaction, or retain a heritage language while developing new academic strategies. Institutional support and exclusion influence these opportunities. Cross-sectional comparisons between newcomers and longer-established students cannot show that every individual follows the same trajectory or that cultural contact alone caused a learning difference.||The models are useful to the extent that they organize questions about multiple dimensions and changing contexts. They become less explanatory when categories are treated as fixed psychological types or language use is mistaken for a complete adaptation score. A justified conclusion combines the learner’s own account with appropriate measures of participation, learning and opportunity, preserving both continuity of identity and the possibility of developmental change.''',context='learning-cognition',concepts=['measurement','change'],source='acculturation')

PACKS=[]
def pack(token,num,title,code,context,stimulus,figure,geometry,tasks,checks,sources):
    """Every item repeats all necessary sources; no dependence on another item."""
    assert len(tasks)==4
    prefix=f'{token.upper()}-{num:02}'
    intro=f'**Stimulus pack {prefix}: {title}.** Sources labelled simulated are original teaching material, including their numbers and participant speech; they are not reports of an actual study. All sources needed for this item are supplied below.\n\n'
    section=['p3-graph','p3-data','p3-qualitative','p3-synthesis']
    dest=CUL if token=='cul' else MOT
    ids=[]
    for j,(demand,answer) in enumerate(tasks):
        q=question(token,len(dest)+1,title+' — '+['display limitation','data interpretation','qualitative inquiry','evidence synthesis'][j],f'{token.upper()}.{code:02}',section[j],intro+stimulus+'\n\n**Task.** '+demand,paras(answer),difficulty='medium' if j in [0,2] else 'hard',context=context,concepts=['measurement','bias'] if j==0 else ['causality','measurement'] if j==1 else ['perspective','responsibility'] if j==2 else ['perspective','causality','measurement'],diagram=figure,caption=f'{prefix}, Source A: original chart of simulated data. Axes and summaries are defined in the sources; error bars are not supplied.')
        q['verification']['notes']=f'{prefix}: original self-contained sources; exact graph geometry and numerical comparisons checked in author ledger. The four questions in this pack assess different demands.'
        dest.append(q); ids.append(q['id'])
        LEDGER.append(evidence(q,'Source-specific author derivation: '+' '.join(paras(answer))+' All relevant limitations concern these source designs, and no simulated result is attributed to a published study.',sources=[URL[x] for x in sources],checks=checks,figure=geometry,alternatives=['Reasoned alternative interpretations grounded in supplied sources are creditworthy; indicative arguments are not additive marks.']))
    PACKS.append(dict(packId=prefix,questionIds=ids,allItemsSelfContained=True,sourceStatus='simulated unless a source is explicitly identified as published',figureData=geometry))

def scatter(xs,ys,xmax,ymax,title,xlabel,ylabel):
    assert len(xs)==len(ys) and all(0<=x<=xmax for x in xs) and all(0<=y<=ymax for y in ys)
    body=text(360,28,title,20,'middle')+text(100,55,ylabel,16)
    for i in range(6):
        y=300-i*44; body+=line(100,y,680,y,'#ddd2c4',1)+text(90,y+5,f'{ymax*i/5:g}',15,'end')
        x=100+i*116; body+=text(x,326,f'{xmax*i/5:g}',15,'middle')
    body+=line(100,300,680,300)+line(100,300,100,80)
    for x,y in zip(xs,ys): body+=f'<circle cx="{100+580*x/xmax:.4f}" cy="{300-220*y/ymax:.4f}" r="6" fill="#8c2833"/>'
    body+=text(390,356,xlabel,17,'middle')+text(360,390,'Simulated observations; each point is one participant.',15,'middle')
    return re.sub(r'font-size="(\d+)"',lambda m:f'font-size="{max(26,int(m[1]))}"',svg(body,720,410))

def phase_lines(labels,series,maxval):
    body=text(360,29,'Source A: simulated optional practice',20,'middle')+text(95,58,'Mean minutes in a ten-minute opportunity',16)
    for i in range(6):
        y=300-i*44; body+=line(95,y,680,y,'#ddd2c4',1)+text(84,y+5,f'{maxval*i/5:g}',15,'end')
    body+=line(95,300,680,300)+line(95,300,95,80)
    xx=[150,390,630]
    for (name,values),colour in zip(series.items(),['#8c2833','#145c6d']):
        for k,(x,v) in enumerate(zip(xx,values)):
            y=300-v*220/maxval
            body+=f'<circle cx="{x}" cy="{y}" r="5" fill="{colour}"/>'
            if k: body+=line(xx[k-1],300-values[k-1]*220/maxval,x,y,colour,3)
        body+=text(115 if name=='Reward' else 450,365,name,26,fill=colour)
    for x,label in zip(xx,labels):body+=text(x,332,label,16,'middle')
    body+=text(360,410,'Group means; individual changes not shown.',26,'middle')
    return re.sub(r'font-size="(\d+)"',lambda m:f'font-size="{max(26,int(m[1]))}"',svg(body,720,435))

pack('cul',1,'Translating distress',1,'health-wellbeing',
'''**Source A — simulated survey.** Forty adults in each of two fictional language communities complete the same literally translated distress questionnaire (0–40; larger scores indicate more reported distress). Means are 24 in community A and 32 in B. Recruitment is through community centres. Source A is the accompanying graph; no spread or uncertainty estimates are given.

**Source B — simulated wording check.** A separate sample of twelve bilingual adults completes literal and locally adapted forms in counterbalanced order. Mean scores are 31 on the literal form and 25 on the local form. No individual paired scores or uncertainty estimates are supplied.

**Source C — simulated interviews.** A clinic employee interviews volunteers in a treatment room and asks, “How much does this difficult culture make you worry?” One participant says, “I use that word for ordinary concern for relatives, not illness.” Another says, “Some worries really do stop me sleeping.” The employee plans to classify every mention of worry as evidence of poor mental health.''',
bars(['A','B'],[24,32],40,title='Source A: simulated distress scores',ylabel='Mean questionnaire score (0–40)'),
{'type':'bar','labels':['A','B'],'values':[24,32],'baseline':0,'maximum':40,'plotBaselineY':300,'plotTopY':75,'mapping':'y=300−value×225/40; both bars use the same linear scale; no error bars.'},[
('Explain one limitation of the graph in Source A for concluding that most people in B are more distressed than most people in A.',
'''The graph contains only group means, so it conceals individual variation and overlap. A higher mean in B could coexist with many B participants scoring below A participants.||Without the distributions, the display cannot establish the claim about most individuals. A group-average difference should not be converted into a statement about the typical ordering of people across the two communities.'''),
('Analyse the findings from Source B in relation to the measurement of distress. Use the mean difference, the paired design and the limits of the supplied evidence.',
'''The literal form produces a mean six score points higher than the local form among the same twelve bilingual adults. Because the participants complete both forms, stable differences between different groups of people cannot by themselves explain this within-sample contrast. Counterbalanced order reduces a simple order explanation.||The pattern is compatible with wording or interpretation affecting scores; it does not establish that one form measures true distress while the other is wrong. The measures could differ in coverage as well as phrasing, and completing both may create carryover or sensitization.||No individual paired differences, uncertainty estimates or wider sampling information are given. The findings therefore justify investigating equivalence, but do not establish population-wide bias, statistical significance or a causal cultural difference in underlying distress.'''),
('Discuss bias as a qualitative research consideration in Source C, referring to the interviewer’s position and question wording. Explain one appropriate improvement without treating interview accounts as numerical prevalence data.',
'''Being interviewed by a clinic employee in a treatment room may encourage a medical interpretation or discourage disagreement with perceived authority. The question presupposes that the culture is difficult and causes worry, potentially shaping what participants discuss and how the employee hears it.||Coding every use of worry as poor mental health ignores the participant’s distinction between ordinary relational concern and disrupted sleep. An interviewer should use neutral, open prompts and follow-up questions about meanings and concrete experiences, with reflexive attention to the employee role.||A more private or independently conducted interview could reduce some pressures, while preserving voluntary participation. These changes improve access to varied accounts; they do not transform selected quotations into estimates of how common distress is in either community.'''),
('Evaluate the claim, “Cultural membership determines how distressed people are.” Synthesize at least three supplied sources and apply relevant HL knowledge about culture, reaching a qualified conclusion.',
'''Source A is consistent with different reported distress between the sampled communities, but a mean difference is neither a causal effect nor a rule about every member. Culture may shape how concerns are experienced and expressed, yet community-centre recruitment, material conditions and individual variation also require consideration. The display provides no basis for treating membership as destiny.||Source B directly challenges a simple interpretation of the questionnaire comparison. Changing wording within a bilingual sample shifts scores by six points, suggesting that the operational definition is sensitive to language and local meaning. HL knowledge of emic and etic approaches explains why a shared comparative construct must be established rather than assumed. This check does not reveal a corrected cultural effect because the sample and comparison are different from Source A.||Source C adds evidence about meaning and researcher influence. Ordinary concern for relatives is not automatically equivalent to disabling worry, and the leading clinic question may encourage a particular narrative. At the same time, the account of disrupted sleep should not be dismissed merely because measurement is imperfect. Culture can be relevant without either medicalizing every expression or denying genuine difficulty.||A defensible conclusion is that culture can influence meanings, practices and social circumstances associated with distress, but these sources do not show determination by membership. Stronger comparison would combine locally informed construct development, equivalent measures, diverse sampling and evidence about contextual conditions. Synthesis should retain both common human experiences and culturally situated meanings while avoiding a deterministic inference from one translated mean score.''')],
[assertion('Source A mean difference',32-24,8),assertion('Source B paired-form mean difference',31-25,6)],['equivalence','qualitative'])

pack('cul',2,'Helping, age and local expectations',2,'human-development',
'''**Source A — simulated observation.** In each of two fictional communities, ten four-year-olds and ten eight-year-olds are each observed during two opportunities to assist with a shared activity. The graph shows the percentage of the twenty opportunities per age/community group in which help occurs: A age four, 60%; A age eight, 80%; B age four, 40%; B age eight, 80%. Different children are observed at the two ages. No child-level distribution is displayed.

**Source B — simulated task comparison.** In a separate sample of ten eight-year-olds per community, the adult explicitly invites help and demonstrates the unfamiliar routine. Help occurs in eighteen of twenty opportunities in each community. The new sample is not a longitudinal follow-up of Source A.

**Source C — simulated caregiver interviews.** Caregivers recruited by a school director discuss what children learn about helping. One says, “Children should notice what is needed.” Another says, “They should ask before touching another person’s materials.” The director proposes coding the second account as a lack of caring, without asking for examples.''',
bars(['A: four','A: eight','B: four','B: eight'],[60,80,40,80],100,title='Source A: simulated helping opportunities',ylabel='Opportunities with help (%)'),
{'type':'bar','labels':['A: four','A: eight','B: four','B: eight'],'values':[60,80,40,80],'denominator':'20 opportunities per bar; ten children per group; not twenty independent children','baseline':0,'maximum':100,'mapping':'y=300−value×2.25; all bar heights derive from the stated proportions.'},[
('Explain one limitation of Source A’s graph for comparing how consistently individual children help.',
'''The bars summarize opportunities, not individual children’s patterns. Two opportunities from each child are combined, so the same percentage could arise from a few consistent helpers or from help spread across more children.||The graph therefore cannot show individual consistency or justify treating the twenty opportunities as twenty independent children. Child-level observations would be needed for that inference.'''),
('Analyse the findings from Source A in relation to developmental change and a possible community difference in helping. Use appropriate comparisons and the study design.',
'''In community A the older group is twenty percentage points higher than the younger group; in B the difference is forty points. Both eight-year-old groups show help in 80% of opportunities, while the younger A group is twenty points higher than the younger B group. The community contrast therefore depends on age.||Different children are observed at four and eight, so the age differences are not measured changes within the same individuals. Experience, maturation or cohort circumstances could contribute; the findings do not establish a common developmental timetable.||The percentages combine two opportunities per child, not twenty independent children. Without individual patterns, uncertainty or evidence that helping has equivalent meaning, the results cannot establish that one community’s children are generally less caring or that cultural membership caused the observed differences.'''),
('Discuss credibility as a qualitative research consideration in Source C, referring to recruitment and the interpretation of contrasting accounts. Suggest a justified improvement.',
'''The two accounts may describe different norms about appropriate assistance rather than different amounts of caring. Treating asking permission as a deficit imposes the director’s preferred meaning and may miss how children learn respect for others’ belongings.||Recruitment through the director may privilege families comfortable with school expectations or encourage socially approved accounts. A researcher should ask neutral follow-up questions for concrete situations, seek contrasting caregivers and explain the researcher’s relationship to the school.||Analysis should consider the meaning of action within each setting and retain disagreement rather than forcing every account into one valued category. Such inquiry can illuminate enculturation processes, but selected interviewees cannot establish that all families in a community teach the same norm.'''),
('Evaluate the claim, “Less spontaneous helping indicates slower prosocial development.” Synthesize at least three supplied sources and apply relevant HL knowledge about culture.',
'''Source A provides a descriptive age-by-community pattern, not direct evidence of developmental speed. Older children help more often in each community, but different children were observed and the eight-year-old groups are identical on this summary. Calling the younger B group slower assumes that spontaneous helping in this particular activity is an equivalent indicator of prosocial development everywhere.||Source B makes that assumption less secure. When an adult invites help and demonstrates the routine, the separate samples show equal rates of assistance. The change could concern permission, task familiarity or social expectations rather than underlying willingness to help. Because several design features and participants differ, the sources cannot isolate the explanation, but they show why performance should not be confused with a complete disposition.||Source C supplies a plausible cultural meaning: noticing a need and asking permission can both express concern within different expectations. Enculturation can transmit these norms through models, participation and feedback. An emic perspective would investigate their meanings, while an etic comparison would require a functionally equivalent helping task. Neither approach warrants romanticizing every practice or assuming all children in one community are alike.||The claim is therefore insufficiently supported. Spontaneous assistance may be one useful indicator, but developmental conclusions need repeated observations, relevant opportunities and locally intelligible measures. Longitudinal evidence and inquiry into children’s understanding would help distinguish acquired norms, task knowledge and maturation. A qualified synthesis recognizes real behavioural differences while resisting an untested cultural ranking of caring or developmental competence.''')],
[assertion('A age contrast in percentage points',80-60,20),assertion('B age contrast in percentage points',80-40,40),assertion('Prompted helping percentage',18/20*100,90)],['learning','equivalence'])

pack('cul',3,'Participation and access after migration',3,'human-relationships',
'''**Source A — simulated newcomer survey.** Eighty adult newcomers are placed into four equally sized profiles using two self-report dimensions: heritage maintenance (H) and wider-society participation (W). The graph shows mean belonging on a 1–5 scale: H+W+, 4.2; H−W+, 4.0; H+W−, 3.8; H−W−, 3.6. The graph’s vertical axis runs from 3 to 5, not the full response range. Profiles are measured, not randomly assigned.

**Source B — simulated service follow-up.** A separate group of twenty newcomers gains access to an evening community centre after bus services improve. Mean belonging rises from 3.5 before the change to 4.0 three months later. There is no comparison group and several other services also change.

**Source C — simulated interviews.** A service worker interviews only people who attend daytime events. One participant says, “I manage this daytime event, but my shift and the bus timetable prevent other activities.” Another says, “Keeping our language at home helps me feel connected.” The worker plans to describe low participation as rejection of the wider community.''',
bars(['H+W+','H−W+','H+W−','H−W−'],[4.2,4.0,3.8,3.6],5,baseline=3,title='Source A: simulated belonging profiles',ylabel='Mean belonging (scale 1–5)'),
{'type':'bar','labels':['H+W+','H−W+','H+W−','H−W−'],'values':[4.2,4.0,3.8,3.6],'baseline':3,'maximum':5,'mapping':'y=300−(value−3)×112.5; intentional truncated baseline explicitly disclosed for critique.'},[
('Explain how one feature of Source A’s graph could exaggerate a viewer’s impression of differences in belonging.',
'''The bars start at a score of three, although the response scale begins at one. This makes the visible bar heights look more different in relative size than they would on the complete response scale.||The highest and lowest means differ by 0.6 scale points; the truncated display cannot turn that into a proportional difference in psychological belonging or show that one profile has twice as much belonging.'''),
('Analyse the findings from Source A in relation to the claim that adopting the H+W+ profile causes greater belonging. Use score comparisons and the design of this survey.',
'''The H+W+ mean is 4.2, 0.6 points above H−W− and 0.2 above H−W+. The ordering is compatible with a relationship between the measured orientations and belonging in this sample, but the full response scale and truncated display should be distinguished. Ratios of visible bar heights are not ratios of belonging.||Profiles were measured rather than assigned. Resources, existing relationships, exclusion or access to institutions could influence both participation and belonging, while people who already feel included may participate more. Neither causal direction is isolated by the survey.||Equal profile sizes simplify the comparison but do not establish representative sampling or equivalent interpretation of the scale. Missing variability prevents a confident judgment about precision or overlap. The data support a descriptive association, not a guarantee that adopting a category causes adjustment.'''),
('Discuss bias as a qualitative research consideration in Source C, referring to sampling and interpretation. Explain how a qualitative researcher could respond.',
'''Interviewing only daytime attendees excludes people whose work, transport or caring responsibilities prevent attendance. Their absence may be central to understanding low participation, so the sample can systematically omit relevant perspectives.||The interpretation also mistakes constrained access for cultural rejection. The shift-and-bus account directly challenges that inference, while maintaining a home language does not imply avoiding wider participation. Purposively seeking nonattendees through optional, accessible interviews would broaden the relevant accounts.||Researchers should use neutral prompts about goals, opportunities and experiences, protect confidentiality and avoid pressuring service users. They should retain conflicting evidence rather than force it into a preferred acculturation label. A richer interpretation still would not make this small qualitative sample a population prevalence estimate.'''),
('Evaluate the claim, “Newcomers can achieve belonging simply by choosing integration.” Synthesize at least three supplied sources and apply relevant HL knowledge about culture.',
'''A two-dimensional acculturation framework makes integration a useful description of valuing heritage maintenance alongside wider participation. Source A’s H+W+ profile has the highest reported belonging, so the claim has some descriptive support in this sample. However, profiles were measured rather than assigned, and the truncated graph can magnify apparent differences. The result does not establish a prescription or a causal effect.||Source B shows that opportunities change alongside belonging. Improved transport and access precede a half-point rise, making a purely individual-choice account incomplete. Other service changes and the absence of a comparison group mean that transport itself is not isolated, but the design directs attention to structural conditions that may enable or constrain participation.||Source C explains why those conditions matter. Wanting to participate is compatible with being unable to attend, and heritage-language maintenance can sustain relationships without preventing wider engagement. Sampling only current attendees would obscure some of these constraints. HL cultural knowledge should distinguish individual orientations from the settlement context and recognize that acculturation categories are neither fixed personality types nor complete measures of adjustment.||A qualified conclusion is that integration may be associated with belonging under supportive conditions, but simply instructing newcomers to choose it is insufficient and risks misplaced blame. Stronger evidence would combine appropriate longitudinal comparisons with inclusive qualitative inquiry and equivalent measures of belonging. Responsibility for inclusion also lies with institutions and communities, whose accessibility and acceptance affect which orientations can be enacted.''')],
[assertion('Profile score range',4.2-3.6,0.6),assertion('Follow-up score increase',4.0-3.5,0.5)],['acculturation','equivalence','qualitative'])

pack('cul',4,'Visible choices and task uncertainty',4,'learning-cognition',
'''**Source A — simulated discussion task.** The same fifty adult learners first make a visible choice after hearing a group majority, then later give a confidential response about the same task. Thirty-eight match the majority publicly and twenty-four match it privately. The graph shows 76% and 48%. Individual response transitions are not provided; everyone completes the public phase first.

**Source B — simulated experiment.** Forty different adults are randomly assigned to a clearly specified task or an ambiguous version. They hear the same majority recommendation. Four of twenty in the clear condition and fourteen of twenty in the ambiguous condition choose the majority answer. There is no manipulation of cultural membership.

**Source C — simulated learner interviews.** A tutor interviews volunteers from their own discussion class. One says, “I did not want to embarrass someone publicly.” Another says, “I thought the others had relevant experience.” The tutor intends to code every majority match as obedience, despite there being no authority command.''',
bars(['Public first','Private later'],[76,48],100,title='Source A: simulated majority matches',ylabel='Participants matching majority (%)'),
{'type':'bar','labels':['Public first','Private later'],'values':[76,48],'baseline':0,'maximum':100,'denominators':[50,50],'paired':True,'mapping':'Each bar y=300−percent×2.25. Same fifty people; graph does not encode individual transitions.'},[
('Explain why Source A’s graph cannot establish that exactly fourteen learners changed their private belief.',
'''The bars show aggregate public and later private responses, not each person’s response transition or underlying belief. Fourteen fewer people match the majority in the later phase, but the display does not identify who switched in either direction.||Moreover, a public response can reflect social accommodation rather than belief. The graph therefore supports a net response difference, not an exact count of private belief changes.'''),
('Analyse the findings from Source A in relation to public agreement and private acceptance. Include the percentage-point contrast and limits on identifying a causal mechanism.',
'''Public majority matching is 76%, compared with 48% in the later confidential response, a 28-percentage-point net difference. This is compatible with some visible agreement reflecting social evaluation rather than private acceptance, but the aggregate counts do not reveal individual transitions or private beliefs directly.||Everyone completes the public phase first. Reflection, repeated exposure, memory or a wish to respond consistently could contribute to the later response, so privacy is confounded with order and time. The difference does not isolate normative influence as a cause.||Almost half still match privately, which could reflect agreement, perceived expertise or continued social concerns. The source does not measure those motives or manipulate cultural membership. It supports a descriptive public–private contrast while leaving multiple psychological explanations open.'''),
('Discuss bias as a qualitative research consideration in Source C, referring to the tutor’s role and coding plan. Propose a justified way to improve it.',
'''Learners may soften disagreement with their own tutor or give accounts that present them as cooperative and competent. The tutor should reflect on how that relationship shapes participation, questioning and interpretation, rather than assume the interview offers transparent access to motives.||Coding every match as obedience ignores the absence of a command and suppresses distinctions between avoiding embarrassment and seeking accurate information. Open follow-ups about the actual decision could clarify those meanings and allow mixed or alternative accounts.||An independent, confidential interviewer and purposive inclusion of learners who did not match the group could reduce some limitations. These measures improve the range and interpretation of accounts, but retrospective explanations remain situated reports rather than direct proof of the mechanism that caused each response.'''),
('Evaluate the claim, “Culture makes learners blindly obey a majority.” Synthesize at least three supplied sources and apply relevant HL knowledge about culture.',
'''The claim combines several unestablished inferences. Source A shows more public than confidential majority matching, which is compatible with sensitivity to social evaluation. It does not measure cultural membership or demonstrate blind belief change. Fixed ordering and aggregate reporting also limit what can be learned about individual transitions. Conformity to a majority should not be relabeled obedience where no authority command occurs.||Source B offers stronger causal evidence about a different factor: ambiguity. Random assignment produces substantially more matching when the task is uncertain. This is consistent with informational influence, where relying on others can be an intelligible attempt to improve accuracy. It does not show that the majority is correct, but it challenges an explanation based solely on unthinking submission.||Source C adds potentially different meanings, including avoiding public embarrassment and respecting perceived expertise. A cultural perspective can examine learned norms about disagreement, relational obligations and what counts as knowledgeable participation. However, the tutor’s role and proposed coding may impose a single interpretation. Emic attention to meaning and an etic interest in shared social-influence processes can complement each other without turning communities into fixed types.||The evidence therefore supports a conditional account of social influence shaped by visibility, uncertainty and interpretation. Culture may contribute to the norms learners use, but it has not been manipulated or adequately measured in these sources. A defensible conclusion rejects inevitability and calls for comparable tasks, appropriate cultural measures and inclusive accounts of learners’ reasons. Following a majority is not by itself evidence of irrationality, obedience or a uniform cultural disposition.''')],
[assertion('Public majority percentage',38/50*100,76),assertion('Private majority percentage',24/50*100,48),assertion('Public-private percentage points',76-48,28),assertion('Ambiguity contrast percentage points',(14-4)/20*100,50)],['equivalence','identity','qualitative'])

pack('cul',5,'Objects, contexts and what a task asks',4,'learning-cognition',
'''**Source A — simulated recognition task.** Twenty adults in each of two fictional communities complete ten object and ten contextual-relation trials. Mean percentage correct is A objects 80%, A relations 65%, B objects 70%, B relations 78%. The same people complete both task types; the graph contains group means, no individual distributions or uncertainty estimates. Task instructions are translated locally.

**Source B — published summary.** Chua et al. (2005) observed different object/background eye movements in American and Chinese graduate students (not Source A). [Primary article](https://pmc.ncbi.nlm.nih.gov/articles/PMC1194960/)

**Source C — published summary.** Rayner et al. (2007) did not reproduce that main scene-viewing pattern, although other eye-movement differences occurred. [Primary article](https://pmc.ncbi.nlm.nih.gov/articles/PMC2048814/)

**Source D — simulated interviews.** Bilingual researchers interview volunteers after Source A. One says, “I thought the instructions wanted me to remember the route between objects.” Another says, “I concentrated on naming each item.” The team initially plans to classify every comment as proof of a fixed national thinking style.''',
bars(['A: obj','A: rel','B: obj','B: rel'],[80,65,70,78],100,title='Source A: simulated recognition accuracy',ylabel='Mean correct responses (%)'),
{'type':'bar','labels':['A: object','A: relation','B: object','B: relation'],'values':[80,65,70,78],'baseline':0,'maximum':100,'pairedWithinCommunity':True,'participantN':[20,20],'trialsPerPersonPerTask':10,'mapping':'y=300−percent×2.25; task order/individual variation are not depicted.'},[
('Explain one limitation of Source A’s graph for concluding that any randomly chosen person from A will outperform any person from B on object recognition.',
'''The graph displays averages without the individual distributions, so it conceals possible overlap between communities. A ten-point mean advantage for A on the object task does not imply that all A participants score above all B participants.||The conclusion about any pair of individuals therefore goes beyond the group-level information. The graph would need individual data to assess the extent of overlap, and even that would not guarantee performance outside this sample.'''),
('Analyse the pattern in Source A and explain why it does not support a general ranking of the communities’ cognitive ability. Use appropriate comparisons and the task design.',
'''A is ten percentage points higher on object recognition, whereas B is thirteen points higher on contextual relations. The direction reverses across tasks, so there is no consistent advantage supporting a general ranking of cognitive ability. Within A, object accuracy exceeds relation accuracy by fifteen points; within B, relation accuracy exceeds object accuracy by eight points.||Both tasks are completed by the same people, so the group summaries should not be treated as independent samples of different individuals for every bar. The many trials likewise do not create hundreds of independent participants.||Differences in instructions, familiarity or learned attention strategies could contribute to the pattern. The data describe performance on these measures, not an innate or fixed cultural capacity, and missing variability limits the precision of any comparison.'''),
('Discuss credibility as a qualitative research consideration in Source D. Explain how the interviews could investigate task interpretation without imposing fixed cultural labels, referring to researcher positioning and contrasting accounts.',
'''The accounts suggest different interpretations of what the task required, which could affect attention and recognition. Researchers should probe how participants understood the instructions and ask for concrete examples rather than presuppose a national thinking style.||Bilingual researchers can notice translation nuances, but their own cultural expectations and involvement in the task still influence questioning and interpretation. Reflexive records and transparent explanation of coding choices can make that influence examinable.||Contrasting accounts should be retained, including variation within each community and explanations that do not fit an object–context dichotomy. Purposively seeking varied performance levels and less confident participants, rather than relying only on volunteers, would broaden relevant experiences. The interviews can clarify meaning and generate explanations, but cannot independently prove that a cultural trait caused the recognition pattern.'''),
('Evaluate the claim, “Culture fixes whether people think about objects or relationships.” Synthesize at least three supplied sources, including the replication evidence, and apply relevant HL knowledge.',
'''Source A is consistent with different task-related patterns, but its crossing mean differences do not show a general ability hierarchy or a fixed way of thinking. The same people perform both types of trial, and a community average leaves room for extensive individual overlap. Translation and familiarity could influence which strategies the task elicits.||Source B provides published evidence that attention allocation differed in particular samples and tasks. It makes cultural influences worth investigating, but national-background groups were not randomly assigned and eye movements are not a complete measure of thought. A plausible cultural explanation involves learned practices and expectations, not a claim that every member possesses an immutable cognitive type.||Source C qualifies the evidential picture by reporting nonreplication of the main scene-viewing pattern under another investigation. This does not prove that culture has no influence, but it challenges an unconditional account and directs attention to stimuli, tasks, sampling and operational definitions. Source D offers a further mechanism: participants can interpret instructions differently. Interviews would need careful, reflexive analysis rather than forced cultural categorization.||A balanced conclusion is that culture may shape attention and interpretation through experience, while task demands and individual histories also matter. HL knowledge of emic and etic approaches supports investigating local meanings and establishing comparable measures before generalizing. The sources justify a conditional, revisable explanation, not cultural determinism. Replication and contrasting qualitative accounts strengthen inquiry by revealing where an apparent pattern does or does not generalize.''')],
[assertion('Object between-community contrast',80-70,10),assertion('Relation between-community contrast',78-65,13),assertion('A within-person task-mean contrast',80-65,15),assertion('B within-person task-mean contrast',78-70,8)],['culture','replication','equivalence','qualitative'])

pack('mot',1,'Choice, feasibility and walking participation',1,'health-wellbeing',
'''**Source A — simulated randomized invitation study.** Sixty adult volunteers are randomly assigned to choose among safe walking-session times or receive an assigned time. Each person has eight offered sessions in the first month. Mean attendance is six sessions in Choice and four in Assigned. In the next month both groups receive the same fixed schedule of eight sessions; means are three and three. All sixty provide attendance data. The graph shows these four means without individual variation.

**Source B — simulated mechanism check.** A separate counterbalanced study of twelve adults uses a neutral activity with chosen versus fixed timing. Mean reported autonomy is six versus four on a 1–7 scale, while mean perceived competence is four in both conditions. There is no long-term follow-up or formal mediation analysis.

**Source C — simulated interviews.** A programme leader interviews only regular attendees. One says, “Choosing meant I could fit the walk around my shift.” Another says, “It felt good to decide for myself.” The leader asks, “Why did our choices make you motivated?” No nonattendees are invited.''',
bars(['Choice 1','Fixed 1','Choice 2','Fixed 2'],[6,4,3,3],8,title='Source A: simulated walking attendance',ylabel='Mean attended sessions out of eight'),
{'type':'bar','labels':['Choice M1','Assigned M1','Choice M2','Assigned M2'],'values':[6,4,3,3],'baseline':0,'maximum':8,'participantN':60,'followup':'same people; all have data; schedule changes at month two','mapping':'y=300−sessions×225/8; no error bars.'},[
('Explain one limitation of the graph in Source A for claiming that all participants benefit from being offered a choice.',
'''The graph shows only condition means, so it does not reveal whether attendance rises for every person or whether a subset accounts for the higher first-month mean. Individual variation is hidden even though all participants supplied data.||It therefore supports an average descriptive difference, not the claim that every participant benefits. Individual trajectories and relevant circumstances would be needed to evaluate that stronger statement.'''),
('Analyse the findings from Source A in relation to the claim of a lasting motivational benefit of choice. Use the attendance contrasts and distinguish observed behaviour from a proposed mechanism.',
'''The first-month mean advantage is two sessions out of eight, equivalent to a 25-percentage-point difference in offered sessions attended. In the second month, after both schedules become fixed, the mean difference is zero. The data do not demonstrate a persisting behavioural advantage under those follow-up conditions.||Random assignment strengthens inference about the initial choice-versus-assigned invitation package, but choice may improve practical fit as well as experienced autonomy. Attendance is not a direct measure of either process, and no mechanism measure is reported in this source.||All participants provide data, reducing concern about differential attrition, but the follow-up changes the opportunity structure. A zero follow-up mean contrast does not prove that all psychological benefits vanished or that motivation never changed. The supported conclusion is limited to the recorded participation pattern and the tested conditions.'''),
('Discuss bias as a qualitative research consideration in Source C, referring to recruitment and questioning. Suggest a specific improvement that preserves participants’ freedom to disagree.',
'''Regular attendees may have had more feasible schedules or more positive experiences than nonattendees. Interviewing them alone excludes evidence about why choice failed to help some people, limiting the range of explanations.||The leader’s question presupposes that the programme caused motivation and may encourage praise. The supplied accounts distinguish practical feasibility from feeling volitional; forcing both into a single autonomy explanation would lose that distinction.||An independent interviewer could purposively invite attendees and nonattendees, make clear that services do not depend on participation, and use neutral prompts about decisions and barriers. Contrasting or negative cases should be retained. These changes can improve interpretive breadth, while interviews still do not by themselves estimate the causal effect of choice.'''),
('Evaluate the claim, “Giving people choices automatically creates lasting motivation.” Synthesize at least three supplied sources and apply relevant HL knowledge about motivation.',
'''Source A gives some support for a short-term benefit of the invitation package: random assignment produces higher mean attendance when people can choose a time. However, the advantage disappears when both groups receive a fixed schedule. This does not prove that initial motivation vanished, because follow-up opportunities changed, but it does not establish a lasting behavioural advantage either. Group means also cannot show automatic benefit for everyone.||Source B is compatible with self-determination theory: chosen timing is associated with greater reported autonomy, while competence ratings remain unchanged. Autonomy concerns volition rather than being isolated from others. Nevertheless, this is a separate short-term sample and no mediation analysis links the autonomy reports to the walking outcomes. The mechanism should remain an explanation to investigate rather than a demonstrated causal chain.||Source C supplies two distinguishable accounts. Choice can make attendance practically possible and can feel personally endorsed. The leader’s role, leading prompt and restriction to regular attendees could privilege favourable narratives. These sources therefore leave practical opportunity, preferences and relatedness as relevant alternatives or complementary influences.||The claim is too strong. Choice can support motivation when options are meaningful and feasible, but a nominal choice or an inaccessible schedule may not. A qualified conclusion distinguishes short-term participation, experienced autonomy and a lasting habit, each requiring appropriate evidence. Stronger follow-up would preserve comparable opportunities and include people who did not participate, rather than interpreting all attendance differences as a universal motivational effect.''')],
[assertion('Initial session advantage',6-4,2),assertion('Attendance percentage-point advantage',(6-4)/8*100,25),assertion('Follow-up session advantage',3-3,0),assertion('Autonomy rating contrast',6-4,2)],['motivation','reporting','qualitative'])

ex=[10,20,30,40,50,60,70]; practice=[3,4,5,6,7,8,18]
pack('mot',2,'Confidence, practice time and achievement',4,'learning-cognition',
'''**Source A — simulated individual observations.** Seven adult learners estimate their chance of solving a new puzzle, then choose how many minutes to practise. The graph plots these pairs (confidence percentage, minutes): (10,3), (20,4), (30,5), (40,6), (50,7), (60,8), (70,18). Confidence is measured, not manipulated. Each point represents one learner; no population is randomly sampled.

**Source B — simulated randomized feedback study.** Thirty different adult learners receive either neutral instructions or an encouraging description of the task, with fifteen per condition. Mean self-rated confidence on a 1–7 scale is four after neutral instructions and six after encouragement. Mean improvement on the same ten-point skill test is two points in both conditions. No inferential test or uncertainty estimate is supplied.

**Source C — simulated interviews.** Volunteers from an evening class discuss practice. One says, “I spent longer because I kept getting stuck.” Another says, “I already knew enough, so I finished quickly.” The instructor asks only confident learners for accounts and plans to equate every extra minute with stronger intrinsic interest.''',
scatter(ex,practice,80,20,'Source A: simulated confidence and practice','Estimated chance of success (%)','Optional practice time (minutes)'),
{'type':'scatter','x':ex,'y':practice,'xRange':[0,80],'yRange':[0,20],'mapping':'cx=100+580×confidence/80; cy=300−220×minutes/20; one circle per learner; no fitted or extrapolated line.'},[
('Explain one limitation of this graph for predicting the practice time of highly confident learners outside the observed confidence range.',
'''The observed confidence values run only from 10% to 70%, and the point at 70% has much longer practice than the others. The display provides no observations for learners above that range.||Extending an apparent trend to very high confidence would be extrapolation, strongly influenced by one unusual point. The graph cannot establish that the same pattern continues beyond the values actually observed.'''),
('Analyse the findings from Source A in relation to the claim that increasing confidence necessarily improves learning. Consider the unusual observation and the meaning of the measured variables.',
'''Greater measured confidence is associated with more optional practice in these seven observations, but the 18-minute observation is unusually high. The mean is about 7.29 minutes with it and 5.5 without it, showing its influence on a summary. Removing a valid observation would require justification rather than a wish for a cleaner pattern.||Practice time is not a measure of skill gain: longer time might indicate persistence, difficulty or an inefficient strategy. No achievement outcome is recorded in this source, so the plotted association cannot establish improved learning.||Confidence is measured, not manipulated. Prior knowledge, interest or opportunity could influence both confidence and time. The small non-random sample, whose recruitment method is unspecified, also limits generalization. The source therefore supports an observed relationship in these participants, not a necessary causal pathway from confidence to achievement.'''),
('Discuss credibility as a qualitative research consideration when using Source C to investigate the meaning of practice time. Explain how to avoid presupposing that time measures intrinsic motivation.',
'''The accounts indicate that time can reflect difficulty as well as interest. A learner who finishes quickly may be competent rather than unmotivated, while long practice can involve frustration. Qualitative inquiry should explore participants’ purposes and experiences before assigning one psychological meaning to duration.||Recruiting only confident learners restricts the range of relevant accounts. The instructor’s involvement can also encourage students to give socially approved explanations. Neutral questions and optional recruitment across confidence and time patterns would allow contrasting cases.||The analysis should preserve distinctions such as enjoyment, persistence, obligation and getting stuck, with transparent examples of interpretation. These categories need not be mutually exclusive. Interview evidence can refine the construct but does not convert every minute into a valid unit of intrinsic motivation.'''),
('Evaluate the claim, “Raising learners’ confidence will necessarily increase their achievement.” Synthesize at least three supplied sources and apply relevant HL knowledge about motivation.',
'''Expectancy-related beliefs can influence willingness to attempt a task, so confidence is a plausible component of motivation. Source A is consistent with some association between confidence and time spent practising, but its small non-random sample with unspecified recruitment and unusual high-duration observation prevent a stable general rule. Measured confidence can also reflect prior knowledge rather than cause later practice.||Source B provides a more informative contrast for the causal claim because feedback conditions are randomly assigned. Reported confidence is higher following encouragement, but mean skill gains are the same in the two conditions. This does not prove that confidence can never help, particularly without uncertainty estimates, yet it separates a change in a psychological report from a demonstrated achievement benefit.||Source C clarifies why the proposed pathway is not automatic. Duration can mean interest, persistence, confusion or task inefficiency. HL motivation knowledge can distinguish expectancy, subjective value, competence and intrinsic interest; none is adequately represented by time alone. An instructor’s selective interviews and coding plan would also bias the apparent support for a preferred mechanism.||A qualified conclusion is that appropriately supported confidence may help engagement under some conditions, but achievement also depends on knowledge, strategy, feedback and opportunities. The evidence does not establish necessity or a universal effect of encouragement. Stronger research would validate the confidence measure, examine relevant behavioural processes and assess skill outcomes with adequate follow-up and uncertainty, rather than infer learning from positive self-reports or prolonged practice.''')],
[assertion('Practice total',sum(practice),51),assertion('Practice mean all',sum(practice)/7,51/7),assertion('Practice mean without unusual point',sum(practice[:-1])/6,5.5),assertion('Confidence-report contrast',6-4,2),assertion('Skill-gain contrast',2-2,0)],['motivation','mindset','reporting','qualitative'])

phase={'Reward':[4,9,3],'Comparison':[4,5,5]}
pack('mot',3,'Performance during and after a reward',4,'learning-cognition',
'''**Source A — simulated randomized task study.** Forty adult volunteers are randomly assigned to Reward or Comparison, twenty per group. In each phase they have a ten-minute opportunity to work voluntarily on puzzles. Mean minutes are shown in the graph: before a reward, four in each group; while the Reward group can earn a small token for puzzle completion, nine in Reward and five in Comparison; after token availability ends, three in Reward and five in Comparison. All participants complete every phase. Instructions truthfully explain token availability, and no penalty applies for stopping. The lines join group means, not individual trajectories.

**Source B — simulated separate questionnaire study.** Twelve adults receive feedback emphasizing useful progress and twelve receive controlling feedback emphasizing what they must achieve. Mean reported autonomy on a 1–7 scale is six and three respectively. This study does not measure puzzle persistence or demonstrate a mediating pathway in Source A.

**Source C — simulated interviews.** Participants are interviewed by the token distributor. One says, “I liked the puzzles but felt pushed to keep earning.” Another says, “I did so many during the token phase that I wanted a break.” The interviewer plans to code every reduction in practice as permanent loss of intrinsic interest.''',
phase_lines(['Before','Token phase','After'],phase,10),
{'type':'line','labels':['Before','Token phase','After'],'series':phase,'baseline':0,'maximum':10,'xCoordinates':[150,390,630],'mapping':'y=300−minutes×22; lines connect phase means only; 20 adults per group; no error bars.'},[
('Explain one limitation of the graph for concluding that rewards cause a lasting or permanent loss of intrinsic interest after tokens end.',
'''The graph records only one immediate ten-minute opportunity after tokens end. A reduction during that brief phase cannot show whether lower engagement persists for days or whether participants resume the puzzles after a short break.||Furthermore, minutes of activity are not a direct measurement of intrinsic interest. Fatigue after the token phase could temporarily reduce practice without a permanent change in enjoyment. Longer follow-up under comparable opportunities and an appropriate measure of interest would be needed.'''),
('Analyse the findings from Source A in relation to a lasting loss of motivation after rewards. Use phase contrasts and distinguish performance from a proposed mechanism.',
'''At baseline the groups have the same mean. During token availability Reward exceeds Comparison by four minutes; afterward Reward is two minutes lower. Relative to baseline, Reward decreases by one minute after tokens end while Comparison increases by one. The incentive initially increases activity, followed by lower recorded voluntary engagement.||Random assignment strengthens inference about the full reward sequence, but minutes are not a direct measure of intrinsic interest or autonomy. The study does not separately manipulate the meaning of reward and the greater amount of practice it produces.||Fatigue, satiation or changed expectations could therefore contribute to the later contrast. The immediate post-token phase also does not establish permanence. A proportionate interpretation recognizes the behavioural pattern while leaving the specific motivational mechanism and long-term duration unconfirmed.'''),
('Discuss credibility as a qualitative research consideration in Source C, referring to researcher involvement and the treatment of alternative accounts.',
'''The token distributor is part of the experience participants are describing. Some may avoid criticism, while others may frame their response to explain their behaviour to that person. Reflexive attention to the interviewer’s role is therefore needed, rather than assuming independence from the findings.||The two accounts distinguish perceived pressure from wanting a break after extensive activity. Coding every decline as permanent lost interest ignores this contrast and imposes the researcher’s preferred mechanism. Neutral probes could explore enjoyment, fatigue, choice and expectations over time.||A confidential interviewer not responsible for tokens and purposeful inclusion of varied participation patterns would improve interpretive breadth. Analysis should preserve contrasting cases and distinguish temporary states from claims about lasting motivation. A plausible interpretation can be supported without requiring every account to fit it.'''),
('Evaluate the claim, “External rewards inevitably destroy intrinsic motivation.” Synthesize at least three supplied sources and apply relevant HL knowledge about motivation.',
'''Source A shows that a reward can increase engagement while available and be followed by lower mean voluntary practice. The baseline equality and random assignment strengthen the comparison of the overall reward sequence. Nevertheless, the outcome is minutes of puzzle activity, not a direct measure of enjoyment or the lasting quality of motivation. The immediate incentive benefit should not be ignored when evaluating the later decline.||Self-determination theory provides one account: a reward experienced as controlling may undermine autonomy, while feedback that supports competence can have different implications. Source B is compatible with this distinction because autonomy reports differ under progress-oriented and controlling feedback. It does not show that autonomy mediated Source A’s outcome, since the participants and outcome measures differ. Nor does it establish that all forms of reward are equally controlling.||Source C highlights alternatives and heterogeneity. Feeling pressured is consistent with the autonomy account, whereas wanting a break after extensive practice suggests fatigue or satiation. Both may operate, and an interviewer who distributed tokens could influence what is said. Classifying every reduction as permanent lost interest would erase relevant distinctions between performance, temporary state and intrinsic motivation.||The evidence therefore supports a conditional risk rather than inevitability. Reward meaning, task interest, expectations, competence and choice can affect responses. A stronger test would assess those processes and later voluntary engagement under comparable opportunities, with sufficient follow-up to evaluate persistence. A qualified conclusion recognizes that incentives can change behaviour while rejecting a universal claim that any external reward necessarily destroys intrinsic interest.''')],
[assertion('Token-phase between-group contrast',9-5,4),assertion('Post-token between-group contrast',3-5,-2),assertion('Reward post-baseline change',3-4,-1),assertion('Comparison post-baseline change',5-4,1),assertion('Autonomy-feedback contrast',6-3,3)],['motivation','reporting','qualitative'])

pack('mot',4,'Belonging and the people who remain',3,'human-relationships',
'''**Source A — simulated satisfaction graph.** Two voluntary community programmes recruit forty adults each. People choose whether to join a new Buddy programme or the Usual programme; there is no random assignment. At eight weeks, the ten people still attending Buddy report mean satisfaction 8.5 on a 0–10 scale. The thirty still attending Usual report mean 7.0. The graph displays only those remaining. No satisfaction data are obtained from people who left.

**Source B — simulated attendance register.** Buddy retains ten of its original forty participants and Usual retains thirty of forty. The programmes differ in required meeting frequency as well as the presence of a buddy. No measures of baseline motivation are available.

**Source C — simulated interviews.** A Buddy coordinator interviews two enthusiastic continuing members. One says, “My buddy helped me feel noticed.” Another says, “I enjoy meeting people, but keeping every appointment is demanding.” The coordinator plans to summarize the interviews as proof that the programme motivates all participants.''',
bars(['Buddy: n=10','Usual: n=30'],[8.5,7],10,title='Source A: simulated satisfaction of stayers',ylabel='Mean satisfaction (0–10)'),
{'type':'bar','labels':['Buddy: n=10','Usual: n=30'],'values':[8.5,7],'baseline':0,'maximum':10,'originalN':[40,40],'displayedN':[10,30],'mapping':'y=300−score×22.5; only remaining attendees represented, deliberately identified.'},[
('Explain one limitation of Source A’s graph for comparing the experience of everyone who originally joined the programmes.',
'''The graph excludes all participants who left, and the proportions remaining are very different. Buddy’s mean describes only ten of forty original members, while Usual’s describes thirty of forty.||If leaving is related to dissatisfaction or other experiences, the displayed means selectively represent different subsets. The graph cannot establish average satisfaction for all original members without information about those who are missing.'''),
('Analyse the findings from Source A in relation to the claim that Buddy produces stronger sustained motivation. Include retention and satisfaction comparisons and the limits of this source.',
'''Among those who remain, Buddy’s satisfaction mean is 1.5 points higher. However, Buddy retains 25% of its starting group and Usual retains 75%, a fifty-percentage-point difference favouring Usual. Higher satisfaction among a selected minority is not equivalent to sustained participation across the starting sample.||Retention is not a direct measure of intrinsic motivation: constraints can cause interested participants to leave, and continuing attendance does not prove enjoyment. Satisfaction data from leavers are missing, so full-sample experience cannot be reconstructed.||Participants choose their programme rather than being randomly assigned. Baseline motivation and reasons for leaving are not reported here, so the source neither isolates a buddy effect nor establishes a motivational mechanism. It supports two different descriptive comparisons that should be interpreted together rather than selecting only the favourable one.'''),
('Discuss transferability as a qualitative research consideration in Source C. Explain how a researcher could support a reasoned judgment about whether these accounts illuminate other volunteers’ experiences.',
'''Transferability concerns whether an interpretation may be useful in another relevant context, based on sufficient understanding of the original setting and participants. Two enthusiastic continuing members provide a narrow range of experiences, especially when the intended conclusion concerns all volunteers.||Descriptions of the programme demands, recruitment, participants’ circumstances and the coordinator’s relationship to them would help readers judge contextual fit. Purposive inclusion of former members and varied participation patterns could reveal conditions under which connection or appointment burden matters.||The existing comments already show those potentially different processes. Researchers should retain contrasting accounts and explain analytic decisions rather than present a universal programme effect. Broader qualitative coverage and contextual detail can support a more defensible transfer, but they do not create statistical representativeness or prove how common each experience is elsewhere.'''),
('Evaluate the claim, “Buddy relationships improve motivation for every volunteer.” Synthesize at least three supplied sources and apply relevant HL knowledge about motivation.',
'''Relatedness provides a plausible motivational account: feeling noticed and connected can make an activity more meaningful. Source C’s first account is compatible with that explanation, and Source A shows high satisfaction among Buddy members who remain. These observations make the programme worth investigating, but they concern selected participants rather than every original volunteer.||Source B substantially changes the interpretation. Only a quarter of Buddy’s starting group remains compared with three quarters of Usual’s. Source A’s higher mean can therefore coexist with worse retention because most Buddy members are missing from the satisfaction measure. A group-level satisfaction comparison among survivors cannot establish a universal motivational benefit or describe the experience of those who left.||The designs also leave competing explanations. Participants choose programmes, baseline motivation is unknown and meeting demands differ. Source C explicitly mentions demanding appointments, suggesting that practical burden can coexist with enjoyment and relatedness. HL knowledge should distinguish intrinsic interest, personally endorsed extrinsic goals, social connection and the opportunity to act. Leaving is not automatically evidence of weak motivation, just as staying is not proof of a beneficial buddy effect.||The claim is too strong. Buddy relationships may support some volunteers under feasible conditions, while imposing burdens or failing to meet the needs of others. Stronger evidence would follow all initial participants, investigate missing perspectives and compare programmes with relevant differences controlled. The conclusion should retain a plausible relatedness mechanism without converting a small, positive, self-selected sample into a causal or universal finding.''')],
[assertion('Satisfaction score contrast',8.5-7,1.5),assertion('Buddy retention percentage',10/40*100,25),assertion('Usual retention percentage',30/40*100,75),assertion('Retention percentage-point contrast',(30-10)/40*100,50)],['motivation','reporting','qualitative'])

young=[0,1,1,2,3,4,4,8]; older=[2,3,4,5,6,8,8,8]
pack('mot',5,'Waiting, understanding and a time limit',2,'human-development',
'''**Source A — simulated voluntary waiting task.** Eight six-year-olds and eight ten-year-olds can take one sticker immediately or wait for two. They can stop without penalty. The session ends at eight minutes, so any child still waiting is recorded as eight. Every eight-valued record is a child still waiting at the cap; no child chose to stop at exactly eight minutes. This fictional design assumes parental permission and child assent, with withdrawal freely available. Recorded times in minutes are younger: 0, 1, 1, 2, 3, 4, 4, 8; older: 2, 3, 4, 5, 6, 8, 8, 8. The graph shows means 2.875 and 5.5, not unconstrained maximum waiting times. Different children form the age groups.

**Source B — simulated separate task study.** Sixteen different children complete a sure-reward version and a version where a clearly explained chance determines whether the delayed extra sticker is available. Both descriptions are truthful; order is counterbalanced. Mean recorded wait is six minutes in the sure version and three in the chance version. The study changes expected availability, not children’s age, and does not supply individual differences or uncertainty estimates.

**Source C — simulated caregiver interviews.** A researcher asks volunteers, “Why are younger children so impatient?” One caregiver says, “My child was not sure what the instructions promised.” Another says, “The sticker was not something they wanted.” The researcher plans to code short waits as a stable lack of self-control.''',
bars(['Six years','Ten years'],[sum(young)/8,sum(older)/8],8,title='Source A: simulated recorded waiting',ylabel='Mean wait (minutes; cap eight)'),
{'type':'bar','labels':['Six years','Ten years'],'rawValues':[young,older],'values':[2.875,5.5],'baseline':0,'maximum':8,'participantN':[8,8],'cap':8,'mapping':'y=300−mean×225/8; an eight-minute record is right-censored, not a measured maximum.'},[
('Explain one limitation of the graph for estimating how long the children would be willing to wait if no time limit applied.',
'''The means include children recorded at the eight-minute cap. Those records indicate that the children were still waiting when the session ended, not that eight minutes was their maximum willingness.||The graph hides how far those waits might extend without the cap and therefore cannot estimate unconstrained mean or maximum waiting. Comparing the displayed means as if all observations were complete would overlook the ceiling and censoring.'''),
('Analyse the findings from Source A in relation to the claim that older children have greater self-control. Use the means, capped observations and developmental design.',
'''The older mean exceeds the younger mean by 2.625 recorded minutes. One of eight younger children reaches the cap, compared with three of eight older children: 12.5% and 37.5% respectively are censored. The observed means therefore do not estimate unconstrained willingness to wait.||Different children form the age groups, so the contrast does not show change within individuals. Understanding the instructions, reward value and previous experience could differ alongside age; these possibilities are not separately measured by the waiting outcome.||The sample is also small, and there is variation within both groups. The findings are compatible with an age-related difference in recorded behaviour, but do not isolate a pure self-control capacity or prove that every older child is more mature. This qualification does not establish that self-control is irrelevant; it identifies what the design cannot distinguish.'''),
('Discuss bias as a qualitative research consideration in Source C, referring to the question and coding assumption. Explain a more appropriate approach to the accounts.',
'''The question presupposes that younger children are impatient, encouraging explanations within a deficit frame rather than exploring how children understand the choice. Caregiver volunteers may also differ from families who do not participate, limiting the range of accounts.||The comments identify comprehension and reward value as alternatives to a stable self-control deficit. A researcher should use neutral prompts about the specific task, probe examples and consider how the child interpreted the instructions and valued the sticker.||Coding should preserve those distinctions and contradictory accounts rather than force every short wait into one category. Caregiver reports are indirect perspectives on children’s experience, so they should not be treated as direct access to the child’s motive or as proof of a developmental cause.'''),
('Evaluate the claim, “Longer waiting proves more mature self-control.” Synthesize at least three supplied sources and apply relevant HL knowledge about motivation and development.',
'''Source A shows that the older group has a higher mean recorded wait, but the measure does not transparently reveal a stable self-control capacity. Both groups include children at the session cap, especially the older group, whose willingness beyond eight minutes is unknown. The comparison is cross-sectional and cannot show how each child develops over time. A difference in behaviour is not yet a complete developmental explanation.||Source B makes expectations consequential: the same separate participants wait longer when the additional reward is sure than when its availability depends on a chance. A shorter wait can therefore be consistent with responding to expected outcomes rather than failing to regulate behaviour. This source does not explain the exact age difference in A, but it challenges the assumption that the waiting task isolates one capacity.||Source C adds comprehension and subjective value as relevant interpretations. If the promise is unclear or the sticker is not desired, waiting may not serve the child’s goals. HL motivation knowledge distinguishes expected success or reward from value, while developmental experience can influence understanding. The leading interview question and predetermined deficit code risk making one explanation appear inevitable.||A qualified conclusion is that waiting may provide useful information under well-understood, valued and comparable conditions, but longer waiting does not by itself prove more mature self-control. Stronger evidence would use appropriate developmental comparisons, attend to censored observations and investigate children’s understanding without equating every immediate choice with failure. The sources support a multi-factor account of motivated choice rather than a fixed ranking of children’s maturity.''')],
[assertion('Younger recorded mean',sum(young)/8,2.875),assertion('Older recorded mean',sum(older)/8,5.5),assertion('Age recorded-mean contrast',sum(older)/8-sum(young)/8,2.625),assertion('Younger capped percentage',young.count(8)/8*100,12.5),assertion('Older capped percentage',older.count(8)/8*100,37.5),assertion('Availability mean contrast',6-3,3)],['motivation','reliability','qualitative'])

def main():
    collections=[write_collection('soc',SOC),write_collection('cul',CUL),write_collection('mot',MOT)]
    assert len(LEDGER)==80 and len({r['questionId'] for r in LEDGER})==80
    allq=SOC+CUL+MOT
    assert Counter(q['examSection'] for q in SOC)=={'p1-a':8,'p1-b':16,'p1-c':16}
    assert Counter(q['difficulty'] for q in allq)=={'medium':40,'hard':40}
    assert {q['syllabusCode'] for q in SOC}=={f'SOC.{i:02}' for i in range(1,11)}
    assert set(c for q in SOC for c in q['concepts'])==set(CONCEPTS)
    assert set(q['context'] for q in SOC if q['context']!='general')==set(CONTEXTS)
    for qs in [CUL,MOT]:
        assert Counter(q['examSection'] for q in qs)=={'p3-graph':5,'p3-data':5,'p3-qualitative':5,'p3-synthesis':5}
        assert set(q['context'] for q in qs)==set(CONTEXTS)
        for q in qs:
            task=q['stem'].split('**Task.** ')[1]
            if q['examSection']=='p3-data':
                assert len(set(re.findall(r'Source ([A-D])',task)))==1,(q['id'],task)
            if q['examSection']=='p3-qualitative':
                assert any(term in task for term in ['bias','credibility','transferability'])
    word_checks=[]
    for q in allq:
        words=len(' '.join(s['text'] for s in q['markScheme'][0]['steps']).split())
        floor={3:45,4:70,6:100,15:220}[q['marks']]
        assert words>=floor,(q['id'],words,floor)
        word_checks.append({'questionId':q['id'],'indicativeAnswerWords':words,'minimumTarget':floor})
        assert q['marks']==q['markScheme'][0]['rubric']['maxMarks']
        bands=q['markScheme'][0]['rubric']['bands']
        scores=[x for b in bands for x in range(b['min'],b['max']+1)]
        assert scores==list(range(q['marks']+1))
    report={'status':'author-checks-passed; independent review required','author':'/root/mock_pdf_inventory','firstAssessment':2027,'scope':'40 shared sociocultural questions and 40 additional-HL extension questions; all original prompts, simulated stimuli and native diagrams.','collections':collections,'questionCount':80,'difficultyCounts':dict(Counter(q['difficulty'] for q in allq)),'sectionCounts':dict(Counter(q['examSection'] for q in allq)),'numericAssertions':sum(len(r['numericChecks']) for r in LEDGER),'uniqueNumericAssertions':sum(len(LEDGER[40+i*4]['numericChecks']) for i in range(10)),'diagramRecords':sum(bool(q.get('diagramSvg')) for q in allq),'distinctStimulusPacks':PACKS,'answerWordChecks':word_checks,'records':LEDGER,'openFindings':[],'verificationBoundary':'This is author checking, not independent moderation. Native render review and independent scientific/assessment review are required before release.'}
    dump(DOCS/'social-extensions-author.json',report)
    print(json.dumps({'questions':len(allq),'collections':collections,'diagramRecords':report['diagramRecords'],'numericAssertions':report['numericAssertions'],'uniqueNumericAssertions':report['uniqueNumericAssertions'],'status':report['status']}))

if __name__=='__main__': main()
